const rtdal006425Source0001 = "describe(\"property retrieval\", {\n  it(\"retrieves the properties that exist & errors otherwise\", {\n    foo <- new_class(\"foo\", properties = list(xyz = class_double), package = NULL)\n    obj <- foo(1)\n    expect_equal(prop(obj, \"xyz\"), 1)\n    expect_equal(obj@xyz, 1)\n\n    expect_snapshot_error(prop(obj, \"x\"))\n    expect_snapshot_error(obj@x)\n  })\n  it(\"evalutes dynamic properties\", {\n    foo <- new_class(\"foo\", properties = list(\n      x = new_property(getter = function(self) 1)\n    ))\n    obj <- foo()\n    expect_equal(prop(obj, \"x\"), 1)\n    expect_equal(obj@x, 1)\n  })\n\n  it(\"falls back to `base::@` for non-S7 objects\", {\n    expect_error(\"foo\"@blah, 'object of.+class.+\"character\"')\n    expect_error(NULL@blah, 'object of.+class.+\"NULL\"')\n  })\n})"

const rtdal006425Source0002 = "describe(\"prop setting\", {\n  it(\"can set a property\", {\n    foo <- new_class(\"foo\", properties = list(xyz = class_double))\n    obj <- foo(1)\n\n    prop(obj, \"xyz\") <- 2\n    expect_equal(obj@xyz, 2)\n\n    obj@xyz <- 3\n    expect_equal(obj@xyz, 3)\n  })\n\n  it(\"can set dynamic properties\", {\n    foo <- new_class(\"foo\", properties = list(\n      x = new_property(setter = function(self, value) {\n        self@x <- value * 2\n        self\n      })\n    ))\n    obj <- foo()\n    obj@x <- 1\n    expect_equal(obj@x, 2)\n  })\n\n  it(\"can't set read-only properties\", {\n    foo <- new_class(\"foo\", package = NULL, properties = list(\n      x = new_property(getter = function(self) 1\n    )))\n    obj <- foo()\n    expect_snapshot(obj@x <- 1, error = TRUE)\n  })\n\n  it(\"errors if the property doesn't exist or is wrong class\", {\n    foo <- new_class(\"foo\", properties = list(x = class_double), package = NULL)\n    expect_snapshot(error = TRUE, {\n      obj <- foo(123)\n      obj@foo <- 10\n      obj@x <- \"x\"\n    })\n  })\n\n  it(\"validates all attributes if custom setter\", {\n    foo <- new_class(\"foo\", package = NULL, properties = list(\n      x = new_property(\n        class_double,\n        setter = function(self, value) {\n          self@x <- 123\n          self@y <- value\n          self\n        }\n      ),\n      y = new_property(class_double)\n    ))\n    expect_snapshot(error = TRUE, {\n      obj <- foo(y = 123, x = 123)\n      obj@x <- \"x\"\n    })\n  })\n\n  it(\"validates once after custom setter\", {\n    times_validated <- 0L;  `add<-` <- `+`\n    custom_setter <- function(self, value) {\n      self@x <- as.double(value)\n      self\n    }\n    foo2 <- new_class(\n      \"foo2\",\n      properties = list(x = new_property(class_double, setter = custom_setter)),\n      validator = function(self) {\n        add(times_validated) <<- 1L\n        character()\n      }\n    )\n    obj <- foo2(\"123\")\n    expect_equal(times_validated, 1)\n    obj@x <- \"456\"\n    expect_equal(times_validated, 2)\n  })\n\n  it(\"validates once with recursive property setters\", {\n    times_validated <- 0L;  `add<-` <- `+`\n    foo <- new_class(\n      \"foo\",\n      properties = list(\n        x = new_property(setter = function(self, value) {\n          self@x <- value\n          self@y <- paste0(value, \"_set_by_x_setter\")\n          self\n        }),\n        y = new_property(setter = function(self, value) {\n          self@y <- value\n          self@z <- paste0(value, \"_set_by_y_setter\")\n          self\n        }),\n        z = new_property(class_character)\n      ),\n      validator = function(self) { add(times_validated) <<- 1L; NULL }\n    )\n    out <- foo()\n    expect_equal(times_validated, 1L)\n\n    out@x <- \"VAL\"\n    expect_equal(times_validated, 2L)\n    expect_equal(out@z, \"VAL_set_by_x_setter_set_by_y_setter\")\n  })\n\n  it(\"does not run the check or validation functions if check = FALSE\", {\n    foo <- new_class(\"foo\", properties = list(x = class_double))\n    obj <- foo(123)\n    prop(obj, \"x\", check = FALSE) <- \"foo\"\n    expect_equal(obj@x, \"foo\")\n  })\n\n  it(\"falls back to `base::@` for non-S7 objects\", {\n    x <- \"foo\"\n    expect_error(x@blah <- \"bar\", \"is not a slot in class\")\n  })\n})"

const rtdal006425Source0003 = "describe(\"props<-\", {\n  it(\"validates after setting all properties\", {\n    foo <- new_class(\"foo\",\n      properties = list(x = class_double, y = class_double),\n      validator = function(self) if (self@x > self@y) \"bad\"\n    )\n\n    obj <- foo(1, 2)\n    props(obj) <- list(x = 5, y = 10)\n    expect_equal(obj@x, 5)\n    expect_equal(obj@y, 10)\n  })\n\n  it(\"`check = FALSE` skip validation\", {\n    foo <- new_class(\"foo\",\n      properties = list(x = class_double, y = class_double),\n      validator = function(self) if (self@x > self@y) \"bad\"\n    )\n\n    obj <- foo(1, 2)\n    props(obj, check = FALSE) <- list(x = 2, y = 1)\n    expect_equal(obj@x, 2)\n    expect_equal(obj@y, 1)\n    expect_snapshot(validate(obj), error = TRUE)\n  })\n\n  it(\"has ordinary syntax in set_props()\", {\n    foo <- new_class(\"foo\", properties = list(x = class_double))\n    obj1 <- foo(1)\n    obj2 <- set_props(obj1, x = 2)\n\n    expect_equal(obj1@x, 1)\n    expect_equal(obj2@x, 2)\n  })\n\n  it(\"set_props() skip validation with `.check = FALSE`\", {\n    foo <- new_class(\"foo\",\n      properties = list(x = class_double, y = class_double),\n      validator = function(self) if (self@x > self@y) \"bad\"\n    )\n\n    obj <- foo(1, 2)\n    obj2 <- set_props(obj, x = 2, y = 1, .check = FALSE)\n    expect_equal(obj2@x, 2)\n    expect_equal(obj2@y, 1)\n    expect_snapshot(validate(obj2), error = TRUE)\n  })\n})"

const rtdal006425Source0004 = `describe("property access", {
  it("access en masse", {
    foo <- new_class("foo", properties = list(x = class_numeric, y = class_numeric))
    x <- foo(x = 1, y = 2)
    expect_equal(prop_names(x), c("x", "y"))
    expect_equal(props(x), list(x = 1, y = 2))
    expect_true(prop_exists(x, "x"))
    expect_true(prop_exists(x, "y"))
    expect_false(prop_exists(x, "z"))
  })

  it("can access dynamic properties", {
    foo <- new_class("foo", properties = list(
      x = new_property(getter = function(self) 10),
      y = new_property()
    ))
    x <- foo(y = 2)
    expect_equal(props(x), list(x = 10, y = 2))
  })

  it("can with property-less object", {
    x <- new_class("x")()
    expect_equal(prop_names(x), character())
    expect_equal(props(x), named_list())
    expect_equal(prop_exists(x, "y"), FALSE)
  })

  it("ignore attributes that are not properties", {
    x <- new_class("x")()
    attr(x, "extra") <- 1

    expect_equal(prop_names(x), character())
    expect_equal(props(x), named_list())
    expect_false(prop_exists(x, "extra"))
  })
})`

const rtdal006425Source0005 = `test_that("properties can be NULL", {
  foo <- new_class("foo", properties = list(x = class_any))
  x <- foo(x = NULL)
  expect_equal(x@x, NULL)
  x@x <- 1
  expect_equal(x@x, 1)
  x@x <- NULL
  expect_equal(x@x, NULL)
  expect_equal(prop_names(x), "x")
  expect_equal(props(x), list(x = NULL))
})`

const rtdal006425Source0006 = `describe("new_property()", {
  it("validates getter and settor", {
    expect_snapshot(error = TRUE, {
      new_property(getter = function(x) {})
      new_property(setter = function(x, y, z) {})
    })
  })

  it("validates default", {
    expect_snapshot(error = TRUE, {
      new_property(class_integer, default = "x")
    })
  })

  it("displays nicely", {
    x <- new_property(class_integer, name = "foo")
    expect_snapshot({
      print(x)
      str(list(x))
    })
  })
})`

const rtdal006425Source0007 = `test_that("properties can be base, S3, S4, S7, or S7 union", {
  class_S7 <- new_class("class_S7", package = NULL)
  class_S4 <- methods::setClass("class_S4", slots = c(x = "numeric"))

  my_class <- new_class("my_class",
    package = NULL,
    properties = list(
      anything = class_any,
      null = NULL,
      base = class_integer,
      S3 = class_factor,
      S4 = class_S4,
      S7 = class_S7,
      S7_union = new_union(class_integer, class_logical)
    )
  )
  expect_snapshot(my_class)
  my_obj <- my_class(
    anything = TRUE,
    null = NULL,
    base = 1L,
    S3 = factor(),
    S4 = class_S4(x = 1),
    S7 = class_S7(),
    S7_union = 1L
  )

  # First check that we can set with out error
  expect_error(my_obj@base <- 2L, NA)
  expect_error(my_obj@S3 <- factor("x"), NA)
  expect_error(my_obj@S4 <- class_S4(x = 2), NA)
  expect_error(my_obj@S7 <- class_S7(), NA)
  expect_error(my_obj@S7_union <- 2L, NA)
  expect_error(my_obj@S7_union <- TRUE, NA)

  # Then capture the error messages for human inspection
  expect_snapshot(error = TRUE, {
    my_obj@null <- "x"
    my_obj@base <- "x"
    my_obj@S3 <- "x"
    my_obj@S4 <- "x"
    my_obj@S7 <- "x"
    my_obj@S7_union <- "x"
  })
})`

const rtdal006425Source0008 = `test_that("as_properties normalises properties", {
  expect_equal(as_properties(NULL), list())
  expect_equal(
    as_properties(list(x = class_numeric)),
    list(x = new_property(class_numeric, name = "x")
  ))
  expect_equal(
    as_properties(list(x = new_property(class = class_numeric))),
    list(x = new_property(class_numeric, name = "x")
  ))
  expect_equal(
    as_properties(list(new_property(name = "y"))),
    list(y = new_property(name = "y")
  ))

  # list name wins
  expect_equal(
    as_properties(list(x = new_property(name = "y"))),
    list(x = new_property(name = "x")
  ))
})`

const rtdal006425Source0009 = `test_that("as_properties() gives useful error messages", {
  expect_snapshot(error = TRUE, {
    as_properties(1)
    as_properties(list(1))
    as_properties(list(new_property(class_character)))
    as_properties(list(x = 1))
    as_properties(list(x = class_character, x = class_character))
  })
})`

const rtdal006425Source0010 = `test_that("can validate with custom validator", {
  validate_scalar <- function(value) {
    if (length(value) != 1) {
      "must be length 1"
    }
  }
  prop <- new_property(class_integer, validator = validate_scalar)
  foo <- new_class("foo", package = NULL, properties = list(x = prop))
  expect_snapshot(error = TRUE, {
    f <- foo(x = 1L)
    f@x <- 1:2

    foo(x = 1:2)
  })
})`

const rtdal006425Source0011 = `test_that("prop<- won't infinitly recurse on a custom setter", {
  chattily_sync_ab <- function(self, value) {
    cat("Starting syncup with value:", value, "\n")
    a_value <- paste0("a_", value)
    b_value <- paste0("b_", value)

    cat(sprintf('setting @a <- "%s"\n', a_value))
    self@a <- a_value

    cat(sprintf('setting @b <- "%s"\n', b_value))
    self@b <- b_value

    self
  }

  foo <- new_class("foo", properties = list(
    a = new_property(setter = chattily_sync_ab),
    b = new_property(setter = chattily_sync_ab)
  ))

  expect_snapshot({
    obj <- foo()
    obj@a <- "val"
  })
})`

const rtdal006425Source0012 = `test_that("custom setters can invoke setters on non-self objects", {

  Transmitter <- new_class("Transmitter", properties = list(
    message = new_property(setter = function(self, value) {
      cat("[tx] sending: ", value, "\n")
      receiver@message <<- value
      cat("[tx] saving last sent message.\n")
      self@message <- value
      cat("[tx] finished transmitting.\n")
      self
    })
  ))

  Receiver <- new_class("Receiver", properties = list(
    message = new_property(setter = function(self, value) {
      cat("[rx] receiving: ", value, "\n")
      self@message <- value
      cat("[rx] finished receiving.\n")
      self
    })
  ))

  expect_snapshot({
    receiver <- Receiver()
    transmitter <- Transmitter()

    transmitter@message <- "hello"
    expect_equal(receiver@message, "hello")

    transmitter@message <- "goodbye"
    expect_equal(receiver@message, "goodbye")
  })

})`

const rtdal006425Source0013 = `test_that("custom getters don't infinitely recurse", {
  # https://github.com/RConsortium/S7/issues/403

  someclass <- new_class("someclass", properties = list(
    someprop = new_property(
      class_character,
      getter = function(self) self@someprop,
      setter = function(self, value) {
        self@someprop <- toupper(value)
        self
      }
    )
  ))

  expect_equal(someclass("foo")@someprop, "FOO")
  x <- someclass()
  expect_equal(x@someprop, character())
  x@someprop <- "foo"
  expect_equal(x@someprop, "FOO")

})`

const rtdal006425Source0014 = `test_that("custom setters can call custom getters", {
  # https://github.com/RConsortium/S7/issues/403

  someclass <- new_class("someclass", properties = list(
    someprop = new_property(
      class_character,
      getter = function(self) self@someprop,
      setter = function(self, value) {
        self@someprop <- paste0(self@someprop, toupper(value))
        self
      }
    )
  ))

  x <- someclass("foo")
  expect_equal(x@someprop, "FOO")

  x <- someclass()
  expect_equal(x@someprop, character())

  x@someprop <- "foo"
  expect_equal(x@someprop, "FOO")

  x@someprop <- "foo"
  expect_equal(x@someprop, "FOOFOO")

})`

const rtdal006425Source0015 = `test_that("custom getters don't evaulate call objects", {
  QuotedCall :=  new_class(class_call, properties = list(
    name = new_property(getter = function(self) {
      stopifnot(is.call(self))
      as.character(self[[1]])
    }),
    args = new_property(getter = function(self) {
      stopifnot(is.call(self))
      as.list(self)[-1]
    })
  ), constructor = function(x) {
    new_object(substitute(x))
  })

  cl <- QuotedCall(stop("boom"))
  expect_equal(cl@name, "stop")
  expect_equal(cl@args, list("boom"))

})`

const rtdal006425Source0016 = `test_that("custom setters don't evaulate call objects", {

  Call :=  new_class(class_call, properties = list(
    name = new_property(
      getter = function(self) {
        stopifnot(is.call(self))
        as.character(self[[1]])
      },
      setter = function(self, value) {
        stopifnot(is.call(self), is.name(value))
        self[[1]] <- value
        self
      }
    ),
    args = new_property(
      getter = function(self) {
        stopifnot(is.call(self))
        as.list(self)[-1]
      },
      setter = function(self, value) {
        stopifnot(is.call(self), is.list(value) || is.pairlist(value))
        # self[seq(2, length.out = length(value))] <- value
        # names(self) <- c("", names(value))
        # self
        out <- as.call(c(self[[1]], value))
        attributes(out) <- attributes(self)
        out
      })
  ), constructor = function(name, ...) {
    new_object(as.call(c(as.name(name), ...)))
  })

  cl <- Call("stop", "boom")
  expect_identical(cl@name, "stop")
  expect_identical(cl@args, list("boom"))

  abort <- stop
  cl@name <- quote(abort)
  expect_identical(cl@name, "abort")
  expect_identical(cl[[1]], quote(abort))

  cl@args <- pairlist("boom2")
  expect_identical(cl[[2]], "boom2")
  expect_identical(cl@args, list("boom2"))
  expect_identical(drop_attributes(cl), quote(abort("boom2")))

  cl@args <- alist(msg = "boom3", foo = bar, baz)
  expect_identical(cl@args, alist(msg = "boom3", foo = bar, baz))

  expect_identical(drop_attributes(cl),
                   quote(abort(msg = "boom3", foo = bar, baz)))

})`

