const rtdal006435Source0001 = `safe_save_file <- function(tensors, path, ..., metadata = NULL) {
  if (any(duplicated(names(tensors)))) {
    cli::cli_abort("Duplicated names are not allowed in {.arg tensors}")
  }

  if (is.character(path)) {
    con <- file(path, open = "wb")
    on.exit(
      {
        close(con)
      },
      add = TRUE
    )
  } else {
    con <- path
  }

  write_safe(tensors, metadata, con)
  invisible(path)
}`

const rtdal006435Source0002 = `safe_serialize <- function(tensors, ..., metadata = NULL) {
  con <- rawConnection(raw(), open = "wb")
  on.exit(
    {
      close(con)
    },
    add = TRUE
  )
  safe_save_file(tensors, con, metadata = metadata)
  rawConnectionValue(con)
}`

const rtdal006435Source0003 = `write_safe <- function(tensors, metadata, con) {
  meta <- make_meta(tensors, metadata)
  meta_json <- meta_to_json(meta)
  meta_raw <- charToRaw(meta_json)
  # write the metadatasize as a 64bit int

  writeBin(length(meta_raw), con = con, size = 8L)
  writeBin(meta_raw, con = con)
  # Index-based: tensors[[""]] returns NULL even when "" is a valid name
  for (i in seq_along(tensors)) {
    buf <- safe_tensor_buffer(tensors[[i]])
    writeBin(buf, con = con)
  }
}`

const rtdal006435Source0004 = `meta_to_json <- function(meta) {
  nms <- names(meta)
  if (!any(nchar(nms) == 0)) {
    return(jsonlite::toJSON(meta, auto_unbox = TRUE))
  }

  parts <- vapply(seq_along(meta), function(i) {
    key <- jsonlite::toJSON(nms[i], auto_unbox = TRUE)
    paste0(key, ":", jsonlite::toJSON(meta[[i]], auto_unbox = TRUE))
  }, character(1))
  paste0("{", paste(parts, collapse = ","), "}")
}`

const rtdal006435Source0005 = "make_meta <- function(tensors, metadata) {\n  nms <- names(tensors)\n  meta_ <- structure(\n    vector(mode = \"list\", length = length(tensors)),\n    names = nms\n  )\n\n  # Offsets accumulate past .Machine$integer.max for multi-GB files;\n  # keep them as doubles (exactly representable well past 2^31)\n  pos <- 0\n  # Index-based: tensors[[\"\"]] returns NULL even when \"\" is a valid name\n  for (i in seq_along(tensors)) {\n    meta <- safe_tensor_meta(tensors[[i]])\n    meta$data_offsets <- c(pos, pos + size_from_meta(meta))\n    pos <- meta$data_offsets[2]\n    meta_[[i]] <- meta\n  }\n  # `[[i]] <-` can drop an empty name; restore before appending __metadata__\n  # (whose slot would otherwise make nms the wrong length)\n  names(meta_) <- nms\n\n  if (!is.null(metadata)) {\n    meta_[[\"__metadata__\"]] <- validate_metadata(metadata)\n  }\n\n  meta_\n}"

const rtdal006435Source0008 = `size_from_meta <- function(meta) {
  numel <- prod(as.numeric(meta$shape))

  el_size <- if (meta$dtype == "F32") {
    4L
  } else if (meta$dtype == "F16") {
    2L
  } else if (meta$dtype == "BF16") {
    2L
  } else if (meta$dtype == "F64") {
    8L
  } else if (meta$dtype == "U8") {
    1L
  } else if (meta$dtype == "I8") {
    1L
  } else if (meta$dtype == "I16") {
    2L
  } else if (meta$dtype == "I32") {
    4L
  } else if (meta$dtype == "I64") {
    8L
  } else if (meta$dtype == "BOOL") {
    1L
  } else if (meta$dtype == "U16") {
    2L
  } else if (meta$dtype == "U32") {
    4L
  } else if (meta$dtype == "U64") {
    8L
  } else if (meta$dtype == "F8_E4M3") {
    1L
  } else if (meta$dtype == "F8_E5M2") {
    1L
  } else {
    cli::cli_abort("Unsupported dtype {.val {meta$dtype}}")
  }

  # Doubles, not integers: tensor byte sizes and cumulative offsets can
  # exceed .Machine$integer.max
  numel * el_size
}`

const rtdal006435Source0009 = `validate_metadata <- function(x) {
  if (!rlang::is_list(x)) {
    cli::cli_abort("{.arg metadata} must be a list.")
  }
  if (!rlang::is_named(x)) {
    cli::cli_abort("{.arg metadata} must be a named list.")
  }
  lapply(x, function(item) {
    if (!rlang::is_scalar_character(item)) {
      cli::cli_abort(
        "{.arg metadata} must be a named list of scalar characters."
      )
    }
  })
  x
}`

