const rtdal006439Source0001 = `test_that("can write a safetensors file (torch)", {
  skip_if_not_installed("torch")

  tensors <- list(
    x = torch::torch_randn(10, 10),
    y = torch::torch_randn(5, 5)
  )

  tmp <- tempfile(fileext = ".safetensors")
  safe_save_file(tensors, tmp)

  reloaded <- safe_load_file(tmp, framework = "torch")

  expect_true(torch::torch_allclose(tensors$x, reloaded$x))
  expect_true(torch::torch_allclose(tensors$y, reloaded$y))
})`

const rtdal006439Source0002 = `test_that("with different datatypes (torch)", {
  data_type <- c(
    "float16",
    "bfloat16",
    "float",
    "float64",
    "bool",
    "uint8",
    "int8",
    "int16",
    "int32",
    "int64"
  )

  for (dtype in data_type) {
    x <- list(x = torch::torch_randn(10)$to(dtype = dtype))

    tmp <- tempfile(fileext = ".safetensors")
    safe_save_file(x, tmp)

    reloaded <- safe_load_file(tmp, framework = "torch")

    expect_true(torch::torch_allclose(x$x, reloaded$x))
  }
})`

const rtdal006439Source0003 = `test_that("float8 datatypes round trip on CPU (torch)", {
  skip_if_not_installed("torch", minimum_version = "0.13.0")

  for (dtype in c("float8_e4m3fn", "float8_e5m2")) {
    tensor <- torch::torch_randn(10, device = "cpu")$to(dtype = dtype)
    reloaded <- safe_load_file(
      safe_serialize(list(x = tensor)),
      framework = "torch"
    )

    expect_true(reloaded$x$dtype == tensor$dtype)
    expect_true(torch::torch_equal(
      reloaded$x$to(dtype = "float"),
      tensor$to(dtype = "float")
    ))
  }
})`

const rtdal006439Source0004 = `test_that("metadata validations", {
  tensors <- list(
    x = torch::torch_randn(10, 10),
    y = torch::torch_randn(5, 5)
  )

  tmp <- tempfile(fileext = ".safetensors")

  metadata <- 1
  expect_snapshot_error({
    safe_save_file(tensors, tmp, metadata = metadata)
  })

  metadata <- list(x = 1)
  expect_snapshot_error({
    safe_save_file(tensors, tmp, metadata = metadata)
  })

  metadata <- list(y = c("1", "2"))
  expect_snapshot_error({
    safe_save_file(tensors, tmp, metadata = metadata)
  })

  metadata <- list("a")
  expect_snapshot_error({
    safe_save_file(tensors, tmp, metadata = metadata)
  })
})`

