const rtdal006450Source0001 = `font_google <- function(family, local = TRUE,
                        cache = sass_file_cache(sass_cache_context_dir()),
                        wght = NULL, ital = NULL, display = c("swap", "auto", "block", "fallback", "optional")) {
  stopifnot(is.logical(local))
  if (!is.null(wght)) {
    stopifnot(is.character(wght) || is.numeric(wght))
    wght <- sort(wght)
  }
  if (!is.null(ital)) {
    stopifnot(all(ital %in% c(0, 1)))
    ital <- sort(ital)
  }
  display <- match.arg(display)

  axis_rng <-
    if (is.null(wght) && is.null(ital)) {
      ""
    } else if (is.null(ital)) {
      paste0(":wght@", paste0(wght, collapse = ";"))
    } else if (is.null(wght)) {
      paste0(":ital@", paste0(ital, collapse = ";"))
    } else {
      paste0(":ital,wght@", paste0(
        apply(expand.grid(wght, ital)[, 2:1], 1, paste0, collapse = ","),
        collapse = ";"
      ))
    }

  x <- list(
    family = family,
    local = isTRUE(local), cache = cache,
    href = paste0(
      "https://fonts.googleapis.com/css2?family=",
      family, axis_rng, "&display=", display
    )
  )

  dep_func <- if (x$local) font_dep_google_local else font_dep_link
  font_object(x, dep_func)
}`

const rtdal006450Source0003 = `font_face <- function(family, src, weight = NULL, style = NULL,
                      display = c("swap", "auto", "block", "fallback", "optional"),
                      stretch = NULL, variant = NULL, unicode_range = NULL) {

  x <- dropNulls(list(
    family = quote_css_font_families(family),
    src = src,
    weight = weight,
    style = style,
    display = if (!is.null(display)) match.arg(display),
    stretch = stretch,
    variant = variant,
    unicode_range = unicode_range
  ))

  # Multiple src values are separated by "," (everything else by white space)
  # TODO: src could accept a list of named lists which might give us the
  # opportunity to handle quoting and encoding of URLs
  for (prop in names(x)) {
    collapse <- switch(prop, src = , unicode_range = ", ", " ")
    x[[prop]] <- paste0(x[[prop]], collapse = collapse)
  }
  x$css <- font_face_css(x)

  font_object(x, font_dep_face)
}`

const rtdal006450Source0006 = "font_collection <- function(..., default_flag = TRUE, quote = TRUE) {\n  fonts <- dropNulls(list2(...))\n\n  # Transform syntax like font_collection(google = \"Pacifico\")\n  # into font_collection(font_google(\"Pacifico\"))\n  # the primary motication for doing this is to support a Rmd\n  # syntax like this (for bslib theming):\n  # ---\n  # theme:\n  #   base_font:\n  #     google: Pacifico\n  # ---\n  fonts <- Map(\n    names2(fonts), fonts,\n    f = function(nm, val) {\n      if (identical(nm, \"\")) return(val)\n\n      func <- known_font_helpers[[nm]] %||% rlang::abort(\n        paste0(\n          \"Unsupported argument name: \", nm, \".\\n\",\n          \"Did you want to try one of these names instead: \",\n          paste0(names(known_font_helpers), collapse = \", \"), \"?\"\n        )\n      )\n\n      do.call(func, as.list(val))\n    }\n  )\n\n  families <- lapply(fonts, function(x) {\n    if (is_font_collection(x))\n      return(x$families)\n    if (is.character(x) && isTRUE(all(nzchar(x, keepNA = TRUE))))\n      return(x)\n    stop(\n      \"`font_collection()` expects a collection of `font_google()`, `font_link()`, `font_face()`, and/or non-empty character strings.\",\n      call. = FALSE\n    )\n  })\n\n  families <- unlist(families, recursive = FALSE, use.names = FALSE)\n\n  deps <- lapply(fonts, function(x) {\n    if (is_font_collection(x)) x$html_deps\n  })\n  new_font_collection(\n    families = families,\n    html_deps = unlist(deps, recursive = FALSE, use.names = FALSE),\n    default_flag = isTRUE(default_flag),\n    quote = quote\n  )\n}"

const rtdal006450Source0008 = `new_font_collection <- function(families, html_deps, default_flag = TRUE, quote = TRUE) {
  add_class(
    list(
      families = if (isTRUE(quote)) quote_css_font_families(families) else families,
      html_deps = html_deps,
      default_flag = default_flag
    ),
    "font_collection"
  )
}`

const rtdal006450Source0013 = `font_dep_link <- function(x) {
  htmlDependency(
    font_dep_name(x), get_package_version("sass"),
    head = format(tags$link(
      href = utils::URLencode(x$href),
      rel = "stylesheet"
    )),
    # The src dir doesn't actually matter...this is just a way
    # to pass along <link> tags as a dependency
    src = tempdir(), all_files = FALSE
  )
}`

const rtdal006450Source0015 = `resolve_cache <- function(cache) {
  if (is_cache_object(cache)) return(cache)
  list(
    get_file = function(...) FALSE,
    set_file = function(...) FALSE
  )
}`

const rtdal006450Source0016 = `font_dep_google_local <- function(x) {
  # TODO: memoise::memoise() this or do something similar
  # to output_template() to reduce file redundancy?
  tmpdir <- tempfile()
  dir.create(tmpdir, recursive = TRUE)
  css_file <- file.path(tmpdir, "font.css")

  has_cache <- is_cache_object(x$cache)
  x$cache <- resolve_cache(x$cache)

  css_key <- hash_with_user_agent(x$href)
  css_hit <- x$cache$get_file(css_key, css_file)

  # Even if we have a cache hit on the CSS file, we may need
  # to re-download font file(s) if they've been pruned from the cache
  css <- if (css_hit) readLines(css_file) else read_gfont_url(x$href, css_file)

  # basename() of these url()s contain a hash key of the font data
  urls <- extract_group(css, "url\\(([^)]+)")
  basenames <- basename(urls)

  # If need be, download the font file(s) that the CSS imports,
  # and modify the CSS to point to the local files
  needs_download_message <- TRUE
  Map(function(url, nm) {
    key <- hash_with_user_agent(nm)
    f <- file.path(tmpdir, nm)
    hit <- x$cache$get_file(key, f)
    if (hit) return()
    # In the event we have a CSS cache hit but miss here, url should actually be
    # a local file. In that case, bust the CSS cache, and start over so we know
    # where to find the font files
    if (!grepl("^\\s*http", url)) {
      x$cache$remove(css_key)
      return(font_dep_google_local(x))
    }

    if (needs_download_message) {
      needs_download_message <<- FALSE
      download_msg <- paste0("Downloading google font ", x$family)
      if (has_cache) {
        download_msg <- paste0(download_msg, " to local cache (", x$cache$dir(), ")")
      }
      rlang::inform(download_msg)
    }

    download_file(url, f, quiet = TRUE)
    x$cache$set_file(key, f)
    css <<- sub(url, nm, css, fixed = TRUE)
  }, urls, basenames)

  # Cache the *modified* form of the CSS file
  # (with the local file paths instead of remote URLs)
  if (!css_hit) {
    writeLines(css, css_file)
    x$cache$set_file(css_key, css_file)
  }

  htmltools::htmlDependency(
    font_dep_name(x), get_package_version("sass"),
    src = dirname(css_file),
    stylesheet = basename(css_file),
    all_files = TRUE
  )
}`

const rtdal006450Source0017 = `read_gfont_url <- function(url, file) {

  download_file(
    utils::URLencode(url), file,
    headers = c("User-Agent" = gfont_user_agent()),
    quiet = TRUE
  )
  readLines(file)
}`

const rtdal006450Source0019 = `hash_with_user_agent <- function(x) {
  rlang::hash(paste0(x, gfont_user_agent()))
}`

const rtdal006450Source0021 = "download_file <- function(url, dest, headers = NULL, quiet = FALSE, ...) {\n\n  if (is_installed(\"curl\")) {\n    if (!curl::has_internet()) {\n      warning(\n        \"Looks like you don't have internet access, which is needed to \",\n        \"download and install Google Fonts files. Try either changing \",\n        \"thematic::font_spec(), manually installing the relevant font, or \",\n        \"trying again with internet access.\",\n        call. = FALSE\n      )\n    }\n    handle <- curl::handle_setheaders(curl::new_handle(), .list = headers)\n    return(curl::curl_download(url, dest, handle = handle, quiet = quiet, ...))\n  }\n\n  if (capabilities(\"libcurl\")) {\n    return(download.file(url, dest, method = \"libcurl\", headers = headers, quiet = quiet, ...))\n  }\n\n  stop(\n    \"Downloading Google Font files requires either the curl package or \",\n    \"`capabilities('libcurl')`. \", call. = FALSE\n  )\n}"

