const rtdal006453Source0001 = `sass_options <- function(
  precision = 5,
  output_style = "expanded",
  indented_syntax = FALSE,
  include_path = "",
  source_comments = FALSE,
  indent_type = "space",
  indent_width = 2,
  linefeed = "lf",
  output_path = "",
  source_map_file = "",
  source_map_root = "",
  source_map_embed = FALSE,
  source_map_contents = FALSE,
  omit_source_map_url = FALSE
) {
  if (indent_width > 10) {
    warning("Maximum indent width is 10. Setting to 10...")
    indent_width <- 10
  } else if (indent_width < 0) {
    warning("Minimum indent width is 0. Setting to 0...")
    indent_width <- 0
  }

  indent_type <- switch(
    indent_type,
    tab = "\t",
    space = " ",
    stop("invalid indent type. Please specify \"space\" or \"tab\".")
  )

  indent <- strrep(indent_type, indent_width)

  output_style <- switch(
    output_style,
    nested = 0,
    expanded = 1,
    compact = 2,
    compressed = 3,
    stop("output style not supported.")
  )

  linefeed <- switch(
    linefeed,
    lf = "\n",
    cr = "\r",
    crlf = "\r\n",
    lfcr = "\n\r",
    stop("invalid linefeed.")
  )

  sep <- switch(
    .Platform$OS.type,
    unix = ":",
    windows = ";",
    stop("unknown operating system")
  )

  include_path <- paste(include_path, collapse = sep)

  ret <- list(
    precision = precision,
    output_style = output_style,
    indented_syntax = indented_syntax,
    include_path = include_path,
    source_comments = source_comments,
    indent = indent,
    linefeed = linefeed,
    output_path = output_path,
    source_map_file = source_map_file,
    source_map_root = source_map_root,
    source_map_embed = source_map_embed,
    source_map_contents = source_map_contents,
    omit_source_map_url = omit_source_map_url
  )

  class(ret) <- c("sass_options", class(ret))
  ret
}`

const rtdal006453Source0002 = `sass_options_get <- function(...) {

  args <- if (in_devmode()) {
    list(source_map_embed = TRUE, source_map_contents = TRUE)
  } else {
    list()
  }

  global <- getOption("sass.options", default = list())
  args <- modifyList(args, global)

  local <- verify_sass_options_args(..., .caller = "sass_options_get()")
  args <- modifyList(args, local)

  opts <- do.call(sass_options, args)
  if (length(global)) {
    attr(opts, "sass_options_global") <- global
  }
  opts
}`

const rtdal006453Source0003 = "sass_options_set <- function(...) {\n  opts <- list2(...)\n  if (length(opts) == 0) {\n    stop(\"`...` must be non-empty.\")\n  }\n\n  if (length(opts) == 1) {\n    # sass_options_set(NULL) clears global state\n    if (is.null(`..1`)) {\n      return(options(sass.options = NULL))\n    }\n    # sass_options_set(sass_options_get()) restores state\n    g_opts <- attr(`..1`, \"sass_options_global\")\n    if (length(g_opts) > 0) {\n      return(options(sass.options = g_opts))\n    }\n    # foo <- sass_options_set(foo = \"bar\"); sass_options_set(foo) restores state\n    if (identical(names(opts[[1]]), \"sass.options\")) {\n      return(options(sass.options = opts[[1]]$sass.options))\n    }\n  }\n\n  args <- verify_sass_options_args(..., .caller = \"sass_options_set()\")\n  options(sass.options = args)\n}"

const rtdal006453Source0004 = "verify_sass_options_args <- function(..., .caller) {\n  args <- list2(...)\n  nms <- names2(args)\n  if (any(nms == \"\")) {\n    stop(\"All arguments to `\", .caller, \"` must be named.\", call. = FALSE)\n  }\n  opts <- names(formals(sass_options))\n  bad_nms <- setdiff(nms, opts)\n  if (length(bad_nms)) {\n    stop(\n      \"The following arguments are not supported by `sass_options()`: \",\n      paste(bad_nms, collapse = \", \"),\n      call. = FALSE\n    )\n  }\n  args\n}"

