const rtdal006458Source0001 = `write_utf8 <- function(text, ...) {
  writeBin(charToRaw(enc2utf8(text)), ...)
}`

const rtdal006458Source0002 = `raw_to_utf8 <- function(data) {
  res <- rawToChar(data)
  Encoding(res) <- "UTF-8"
  res
}`

const rtdal006458Source0005 = `get_file_mtimes <- function(files) {
  if (length(files) == 0) return(NULL)

  is_dir <- dir.exists(files)
  all_files <- c(
    files[!is_dir],
    dir(files[is_dir], full.names = TRUE, all.files = TRUE, recursive = TRUE, no.. = TRUE)
  )
  rlang::set_names(file.mtime(all_files), all_files)
}`

const rtdal006458Source0006 = `is_shiny_app <- function() {
  isNamespaceLoaded("shiny") && shiny::isRunning()
}`

const rtdal006458Source0009 = `is_connect_app <- function() {
  if (!is_hosted_app()) {
    return(FALSE)
  }

  info <- shiny::serverInfo()
  if (!is.null(info) && is.list(info) && identical(info$edition, "Connect")) {
    return(TRUE)
  }

  FALSE
}`

const rtdal006458Source0010 = `file.copy2 <- function(from, to, ...) {
  res <- file.copy(from, to, ...)
  if (!all(res)) {
    stop("Error copying files: ", paste0(from[!res], collapse = ", "))
  }
}`

const rtdal006458Source0011 = `dir.create2 <- function(path, ...) {
  res <- dir.create(path, ...)
  if (!res) {
    stop("Error creating directory: ", path)
  }
}`

