const rtdal006480Source0001 = `rescale <- function(x, to, from, ...) {
  UseMethod("rescale")
}`

const rtdal006480Source0002 = `rescale.numeric <- function(
  x,
  to = c(0, 1),
  from = range(x, na.rm = TRUE, finite = TRUE),
  ...
) {
  if (zero_range(from) || zero_range(to)) {
    return(ifelse(is.na(x), NA, mean(to)))
  }
  (x - from[1]) / diff(from) * diff(to) + to[1]
}`

const rtdal006480Source0003 = `rescale.NULL <- function(...) NULL`

const rtdal006480Source0006 = `rescale.POSIXt <- function(
  x,
  to = c(0, 1),
  from = range(x, na.rm = TRUE, finite = TRUE),
  ...
) {
  x <- as.numeric(x)
  from <- as.numeric(from)
  rescale.numeric(x = x, to = to, from = from)
}`

