const rtdal006480Source0012 = `rescale_mid.numeric <- function(
  x,
  to = c(0, 1),
  from = range(x, na.rm = TRUE),
  mid = 0,
  ...
) {
  if (zero_range(from) || zero_range(to)) {
    return(ifelse(is.na(x), NA, mean(to)))
  }

  extent <- 2 * max(abs(from - mid))
  (x - mid) / extent * diff(to) + mean(to)
}`

const rtdal006480Source0013 = `rescale_mid.NULL <- function(...) NULL`

const rtdal006480Source0016 = `rescale_mid.POSIXt <- function(
  x,
  to = c(0, 1),
  from = range(x, na.rm = TRUE),
  mid,
  ...
) {
  x <- as.numeric(as.POSIXct(x))
  if (!is.numeric(from)) {
    from <- as.numeric(as.POSIXct(from))
  }
  if (!is.numeric(mid)) {
    mid <- as.numeric(as.POSIXct(mid))
  }
  rescale_mid.numeric(x = x, to = to, from = from, mid = mid)
}`

