const rtdal006483Source0002 = `breaks_extended <- function(n = 5, ...) {
  n_default <- n
  function(x, n = n_default) {
    x <- x[is.finite(x)]
    if (length(x) == 0) {
      return(numeric())
    }

    rng <- range(x)
    labeling::extended(rng[1], rng[2], n, ...)
  }
}`

const rtdal006483Source0004 = `breaks_pretty <- function(n = 5, ...) {
  force_all(n, ...)
  n_default <- n
  function(x, n = n_default) {
    if (length(x) > 0 && zero_range(range(as.numeric(x), na.rm = TRUE))) {
      return(x[1])
    }
    breaks <- pretty(x, n, ...)
    names(breaks) <- attr(breaks, "labels")
    breaks
  }
}`

const rtdal006483Source0006 = `breaks_timespan <- function(
  unit = c("secs", "mins", "hours", "days", "weeks"),
  n = 5
) {
  unit <- arg_match(unit)
  force(n)
  function(x) {
    x <- as.numeric(as.difftime(x, units = unit), units = "secs")
    rng <- range(x)
    diff <- rng[2] - rng[1]

    if (diff <= 2 * 60) {
      scale <- 1
    } else if (diff <= 2 * 3600) {
      scale <- 60
    } else if (diff <= 2 * 86400) {
      scale <- 3600
    } else if (diff <= 2 * 604800) {
      scale <- 86400
    } else {
      scale <- 604800
    }

    rng <- rng / scale
    breaks <- labeling::extended(
      rng[1],
      rng[2],
      n,
      Q = c(1, 2, 1.5, 4, 3),
      only.loose = FALSE
    )
    as.difftime(breaks * scale, units = "secs")
  }
}`

const rtdal006483Source0007 = `breaks_exp <- function(n = 5, ...) {
  n_default <- n
  default <- extended_breaks(n = n_default, ...)
  function(x, n = n_default) {
    # Discard -Infs
    x <- sort(pmax(x, 0))
    top <- floor(x[2])
    if (top >= 3 && abs(diff(x)) >= 3) {
      unique(c(top - seq_len(min(top, n_default - 1)) + 1, 0))
    } else {
      default(x)
    }
  }
}`

