const rtdal006485Source0001 = `col_numeric <- function(
  palette,
  domain,
  na.color = "#808080",
  alpha = FALSE,
  reverse = FALSE
) {
  rng <- NULL
  if (length(domain) > 0) {
    rng <- range(domain, na.rm = TRUE)
    if (!all(is.finite(rng))) {
      cli::cli_abort("Wasn't able to determine range of {.arg domain}")
    }
  }

  pf <- safePaletteFunc(palette, na.color, alpha)

  withColorAttr("numeric", list(na.color = na.color), function(x) {
    if (length(x) == 0 || all(is.na(x))) {
      return(pf(x))
    }

    if (is.null(rng)) rng <- range(x, na.rm = TRUE)

    rescaled <- rescale(x, from = rng)
    if (any(rescaled < 0 | rescaled > 1, na.rm = TRUE)) {
      cli::cli_warn(
        "Some values were outside the color scale and will be treated as NA"
      )
    }

    if (reverse) {
      rescaled <- 1 - rescaled
    }
    pf(rescaled)
  })
}`

const rtdal006485Source0003 = `getBins <- function(domain, x, bins, pretty) {
  if (is.null(domain) && is.null(x)) {
    cli::cli_abort("{.arg domain} and {.arg x} can't both be NULL")
  }

  # Hard-coded bins
  if (length(bins) > 1) {
    return(bins)
  }

  if (bins < 2) {
    cli::cli_abort(c(
      "Invalid {.arg bins} value ({bins})",
      i = "bin count must be at least 2"
    ))
  }
  if (pretty) {
    base::pretty(domain %||% x, n = bins)
  } else {
    rng <- range(domain %||% x, na.rm = TRUE)
    seq(rng[1], rng[2], length.out = bins + 1)
  }
}`

const rtdal006485Source0004 = `col_bin <- function(
  palette,
  domain,
  bins = 7,
  pretty = TRUE,
  na.color = "#808080",
  alpha = FALSE,
  reverse = FALSE,
  right = FALSE
) {
  # domain usually needs to be explicitly provided (even if NULL) but not if
  # breaks are specified
  if (missing(domain) && length(bins) > 1) {
    domain <- NULL
  }
  autobin <- is.null(domain) && length(bins) == 1
  if (!is.null(domain)) {
    bins <- getBins(domain, NULL, bins, pretty)
  }
  numColors <- if (length(bins) == 1) bins else length(bins) - 1
  colorFunc <- col_factor(
    palette,
    domain = if (!autobin) 1:numColors,
    na.color = na.color,
    alpha = alpha,
    reverse = reverse
  )
  pf <- safePaletteFunc(palette, na.color, alpha)

  withColorAttr(
    "bin",
    list(bins = bins, na.color = na.color, right = right),
    function(x) {
      if (length(x) == 0 || all(is.na(x))) {
        return(pf(x))
      }
      binsToUse <- getBins(domain, x, bins, pretty)
      ints <- cut(
        x,
        binsToUse,
        labels = FALSE,
        include.lowest = TRUE,
        right = right
      )
      if (any(is.na(x) != is.na(ints))) {
        cli::cli_warn(
          "Some values were outside the color scale and will be treated as NA"
        )
      }
      colorFunc(ints)
    }
  )
}`

const rtdal006485Source0005 = `col_quantile <- function(
  palette,
  domain,
  n = 4,
  probs = seq(0, 1, length.out = n + 1),
  na.color = "#808080",
  alpha = FALSE,
  reverse = FALSE,
  right = FALSE
) {
  if (!is.null(domain)) {
    bins <- safe_quantile(domain, probs)
    return(withColorAttr(
      "quantile",
      list(probs = probs, na.color = na.color, right = right),
      col_bin(
        palette,
        domain = NULL,
        bins = bins,
        na.color = na.color,
        alpha = alpha,
        reverse = reverse
      )
    ))
  }

  # I don't have a precise understanding of how quantiles are meant to map to colors.
  # If you say probs = seq(0, 1, 0.25), which has length 5, does that map to 4 colors
  # or 5? 4, right?
  colorFunc <- col_factor(
    palette,
    domain = 1:(length(probs) - 1),
    na.color = na.color,
    alpha = alpha,
    reverse = reverse
  )

  withColorAttr(
    "quantile",
    list(probs = probs, na.color = na.color, right = right),
    function(x) {
      binsToUse <- safe_quantile(x, probs)
      ints <- cut(
        x,
        binsToUse,
        labels = FALSE,
        include.lowest = TRUE,
        right = right
      )
      if (any(is.na(x) != is.na(ints))) {
        cli::cli_warn(
          "Some values were outside the color scale and will be treated as NA"
        )
      }
      colorFunc(ints)
    }
  )
}`

const rtdal006485Source0006 = `safe_quantile <- function(x, probs) {
  bins <- stats::quantile(x, probs, na.rm = TRUE, names = FALSE)
  if (anyDuplicated(bins)) {
    bins <- unique(bins)
    cli::cli_warn(
      "Skewed data means we can only allocate {length(bins)} unique colours not the {length(probs) - 1} requested"
    )
  }
  bins
}`

const rtdal006485Source0007 = `calcLevels <- function(x, ordered) {
  if (is.null(x)) {
    NULL
  } else if (is.factor(x)) {
    levels(x)
  } else if (ordered) {
    unique(x)
  } else {
    sort(unique(x))
  }
}`

const rtdal006485Source0008 = `getLevels <- function(domain, x, lvls, ordered) {
  if (!is.null(lvls)) {
    return(lvls)
  }

  if (!is.null(domain)) {
    return(calcLevels(domain, ordered))
  }

  if (!is.null(x)) {
    return(calcLevels(x, ordered))
  }
}`

const rtdal006485Source0009 = `col_factor <- function(
  palette,
  domain,
  levels = NULL,
  ordered = FALSE,
  na.color = "#808080",
  alpha = FALSE,
  reverse = FALSE
) {
  # domain usually needs to be explicitly provided (even if NULL) but not if
  # levels are specified
  if (missing(domain) && !is.null(levels)) {
    domain <- NULL
  }

  if (!is.null(levels) && anyDuplicated(levels)) {
    cli::cli_warn("Duplicate levels detected")
    levels <- unique(levels)
  }
  lvls <- getLevels(domain, NULL, levels, ordered)

  force(palette) # palette loses scope
  withColorAttr("factor", list(na.color = na.color), function(x) {
    if (length(x) == 0 || all(is.na(x))) {
      return(rep.int(na.color, length(x)))
    }

    lvls <- getLevels(domain, x, lvls, ordered)
    pf <- safePaletteFunc(
      palette,
      na.color,
      alpha,
      nlevels = length(lvls) * ifelse(reverse, -1, 1)
    )

    origNa <- is.na(x)
    x <- match(as.character(x), lvls)
    if (any(is.na(x) != origNa)) {
      cli::cli_warn(
        "Some values were outside the color scale and will be treated as NA"
      )
    }

    scaled <- rescale(as.integer(x), from = c(1, length(lvls)))
    if (any(scaled < 0 | scaled > 1, na.rm = TRUE)) {
      cli::cli_warn(
        "Some values were outside the color scale and will be treated as NA"
      )
    }
    if (reverse) {
      scaled <- 1 - scaled
    }
    pf(scaled)
  })
}`

const rtdal006485Source0013 = `toPaletteFunc.character <- function(pal, alpha, nlevels) {
  if (length(pal) == 1 && pal %in% row.names(RColorBrewer::brewer.pal.info)) {
    paletteInfo <- RColorBrewer::brewer.pal.info[pal, ]
    if (!is.null(nlevels)) {
      # pal_brewer will return NAs if you ask for more colors than the palette has
      colors <- pal_brewer(palette = pal)(abs(nlevels))
      colors <- colors[!is.na(colors)]
    } else {
      colors <- pal_brewer(palette = pal)(RColorBrewer::brewer.pal.info[
        pal,
        "maxcolors"
      ]) # Get all colors
    }
  } else if (
    length(pal) == 1 && pal %in% c("viridis", "magma", "inferno", "plasma")
  ) {
    colors <- pal_viridis(option = pal)(256)
  } else {
    colors <- pal
  }

  colour_ramp(colors, alpha = alpha)
}`

const rtdal006485Source0014 = `toPaletteFunc.matrix <- function(pal, alpha, nlevels) {
  toPaletteFunc(farver::decode_colour(pal), alpha = alpha)
}`

const rtdal006485Source0016 = `filterZeroLength <- function(f) {
  force(f)
  function(x) {
    if (length(x) == 0) {
      character(0)
    } else {
      f(x)
    }
  }
}`

const rtdal006485Source0018 = `filterRGB <- function(f) {
  force(f)
  function(x) {
    results <- f(x)
    if (is.character(results)) {
      results
    } else if (is.matrix(results)) {
      farver::encode_colour(results, from = "rgb")
    } else {
      cli::cli_abort("Unexpected result type {.cls {class(x)}}")
    }
  }
}`

