const rtdal006495Source0005 = `label_time <- function(format = "%H:%M:%S", tz = "UTC", locale = NULL) {
  force_all(format, tz)
  function(x) {
    if (inherits(x, "POSIXt")) {
      format_dt(x, format = format, tz = tz, locale = locale)
    } else if (inherits(x, "difftime")) {
      format(as.POSIXct(x), format = format, tz = tz)
    } else {
      stop_input_type(
        x,
        as_cli("used with a {.cls POSIXt} or {.cls difftime} object"),
        arg = I(as_cli("{.fn label_time}"))
      )
    }
  }
}`

const rtdal006495Source0006 = `label_timespan <- function(
  unit = c("secs", "mins", "hours", "days", "weeks"),
  space = FALSE,
  ...
) {
  unit <- arg_match(unit)
  force_all(...)
  function(x) {
    x <- as.numeric(as.difftime(x, units = unit), units = "secs")
    number(
      x,
      scale_cut = cut_time_scale(space),
      ...
    )
  }
}`

const rtdal006495Source0007 = `format_dt <- function(x, format, tz = "UTC", locale = NULL) {
  if (is.null(locale)) {
    format(x, format = format, tz = tz)
  } else {
    check_installed("stringi")
    format <- stringi::stri_datetime_fstr(format)
    stringi::stri_datetime_format(x, format, tz = tz, locale = locale)
  }
}`

