const rtdal006499Source0002 = `format_log <- function(x, base = 10, signed = NULL, ...) {
  if (length(x) == 0) {
    return(character())
  }
  prefix <- rep("", length(x))
  finites <- x[is.finite(x)]

  signed <- signed %||% any(finites <= 0)
  if (signed) {
    sign <- sign(x)
    prefix[sign == +1] <- "+"
    prefix[sign == -1] <- "-"
    x <- abs(x)
    x[x == 0] <- 1
  }

  exponent <- format(zapsmall(log(x, base = base)), ...)
  text <- paste0(prefix, base, "^", exponent)

  if (signed) {
    text[sign == 0] <- "0"
  }
  text[is.na(x)] <- NA

  text
}`

