const rtdal006503Source0001 = `label_ordinal <- function(
  prefix = "",
  suffix = "",
  big.mark = NULL,
  rules = NULL,
  ...
) {
  force_all(prefix, suffix, big.mark, rules, ...)
  function(x) {
    ordinal(
      x,
      prefix = prefix,
      suffix = suffix,
      big.mark = big.mark,
      rules = rules,
      ...
    )
  }
}`

const rtdal006503Source0003 = `ordinal_french <- function(gender = c("masculin", "feminin"), plural = FALSE) {
  suffix <- switch(match.arg(gender), masculin = "er", feminin = "re")

  label <- list("^1$", ".")
  names(label) <- c(suffix, "e")
  if (plural) {
    names(label) <- paste0(names(label), "s")
  }
  label
}`

const rtdal006503Source0004 = `ordinal_spanish <- function() {
  stats::setNames(list("."), ".\u00ba")
}`

const rtdal006503Source0006 = `ordinal <- function(
  x,
  prefix = "",
  suffix = "",
  big.mark = " ",
  rules = NULL,
  ...
) {
  rules <- rules %||%
    getOption("scales.ordinal.rules", default = ordinal_english())
  na_idx <- is.na(x)
  x <- round(x, digits = 0)
  x[na_idx] <- 1 # replace NAs with dummy value
  out <- utils::stack(lapply(rules, grep, x = x, perl = TRUE))
  out <- out[!duplicated(out$values), ] # only first result should be considered
  ret <- paste0(
    number(
      accuracy = 1,
      x,
      prefix = prefix,
      suffix = "",
      big.mark = big.mark,
      ...
    ),
    out$ind[order(out$values)],
    suffix
  )

  # restore NAs from input vector
  ret[na_idx] <- NA
  names(ret) <- names(x)

  ret
}`

