const rtdal006520Source0001 = `pal_manual <- function(values, type = NULL) {
  force(values)
  fun <- function(n) {
    n_values <- length(values)
    if (n > n_values) {
      cli::cli_warn(
        "This manual palette can handle a maximum of {n_values} values. You have supplied {n}"
      )
    }
    unname(values[seq_len(n)])
  }
  type <- type %||% guess_pal_type(values)
  new_discrete_palette(
    fun,
    type,
    length(values)
  )
}`

const rtdal006520Source0003 = `guess_pal_type <- function(x) {
  if (is.numeric(x)) {
    "numeric"
  } else if (all(is_color(x))) {
    "colour"
  } else {
    typeof(x)
  }
}`

const rtdal006520Source0004 = `is_color <- function(x) {
  # '#' followed by 3,4,6 or 8 hex digits
  grepl("^#(([[:xdigit:]]{2}){3,4}|([[:xdigit:]]){3,4})$", x) |
    x %in% grDevices::colours()
}`

