const rtdal006528Source0003 = `train_discrete <- function(
  new,
  existing = NULL,
  drop = FALSE,
  na.rm = FALSE,
  fct = NA,
  call = caller_env()
) {
  if (is.null(new)) {
    return(existing)
  }
  if (!is.discrete(new)) {
    example <- unique(new)
    example <- example[seq_len(pmin(length(example), 5))]
    cli::cli_abort(
      c(
        "Continuous value supplied to a discrete scale.",
        i = "Example values: {.and {.val {example}}}."
      ),
      call = call
    )
  }
  discrete_range(existing, new, drop = drop, na.rm = na.rm, fct = fct)
}`

const rtdal006528Source0004 = "discrete_range <- function(old, new, drop = FALSE, na.rm = FALSE, fct = NA) {\n  new_is_factor <- is.factor(new)\n  old_is_factor <- is.factor(old) || isTRUE(fct)\n  new <- clevels(new, drop = drop, na.rm = na.rm)\n  if (is.null(old)) {\n    return(new)\n  }\n\n  if (old_is_factor && !is.factor(old)) {\n    old <- factor(old, old)\n  }\n  if (!is.character(old)) {\n    old <- clevels(old, na.rm = na.rm)\n  } else {\n    old <- sort(old, na.last = if (na.rm) NA else TRUE)\n  }\n\n  # If new is more rich than old it becomes the primary\n  if (new_is_factor && !old_is_factor) {\n    tmp <- old\n    old <- new\n    new <- tmp\n    tmp <- old_is_factor\n    old_is_factor <- new_is_factor\n    new_is_factor <- tmp\n  }\n\n  new_levels <- setdiff(new, old)\n\n  # Keep as a factor if we don't have any new levels\n  if (length(new_levels) == 0) {\n    return(old)\n  }\n\n  range <- c(old, new_levels)\n\n  # Avoid sorting levels when dealing with factors. `old` will always be a\n  # factor if either `new` or `old` was a factor going in\n  if (old_is_factor) {\n    return(range)\n  }\n  sort(range, na.last = if (na.rm) NA else TRUE)\n}"

const rtdal006528Source0005 = `clevels <- function(x, drop = FALSE, na.rm = FALSE) {
  if (is.null(x)) {
    character()
  } else if (!is.null(levels(x))) {
    if (drop && !is.character(x)) x <- droplevels(x)

    values <- levels(x)
    if (na.rm) {
      values <- values[!is.na(values)]
    } else if (any(is.na(x))) {
      values <- c(values, NA)
    }

    values
  } else {
    sort(unique(x), na.last = if (na.rm) NA else TRUE)
  }
}`

