const rtdal006531Source0001 = `transform_date <- function() {
  new_transform(
    "date",
    transform = "from_date",
    inverse = "to_date",
    breaks = breaks_pretty(),
    domain = to_date(c(-Inf, Inf))
  )
}`

const rtdal006531Source0004 = `from_date <- function(x) {
  if (!inherits(x, "Date")) {
    cli::cli_abort(
      "{.fun transform_date} works with objects of class {.cls Date} only"
    )
  }
  structure(as.numeric(x), names = names(x))
}`

const rtdal006531Source0005 = `transform_time <- function(tz = NULL) {
  force(tz)
  to_time <- function(x) {
    structure(x, class = c("POSIXct", "POSIXt"), tzone = tz)
  }

  from_time <- function(x) {
    if (!inherits(x, "POSIXct")) {
      cli::cli_abort(
        "{.fun transform_time} works with objects of class {.cls POSIXct} only"
      )
    }
    if (is.null(tz)) {
      tz <<- attr(as.POSIXlt(x), "tzone")[[1]]
    }
    structure(as.numeric(x), names = names(x))
  }

  new_transform(
    "time",
    transform = "from_time",
    inverse = "to_time",
    breaks = breaks_pretty(),
    domain = to_time(c(-Inf, Inf))
  )
}`

const rtdal006531Source0007 = `transform_timespan <- function(
  unit = c("secs", "mins", "hours", "days", "weeks")
) {
  unit <- arg_match(unit)
  new_transform(
    "timespan",
    transform = function(x) {
      structure(
        as.numeric(as.difftime(x, units = unit), units = "secs"),
        names = names(x)
      )
    },
    inverse = function(x) {
      x <- as.difftime(x, units = "secs")
      units(x) <- unit
      x
    },
    breaks = breaks_timespan(unit),
    format = label_timespan(unit)
  )
}`

const rtdal006531Source0011 = `breaks_hms <- function(n = 5) {
  base_breaks <- breaks_timespan("secs", n)
  function(x) {
    hms::as_hms(base_breaks(x))
  }
}`

