const rtdal006533Source0001 = `new_transform <- function(
  name,
  transform,
  inverse,
  d_transform = NULL,
  d_inverse = NULL,
  breaks = extended_breaks(),
  minor_breaks = regular_minor_breaks(),
  format = format_format(),
  domain = c(-Inf, Inf)
) {
  if (is.character(transform)) transform <- match.fun(transform)
  if (is.character(inverse)) inverse <- match.fun(inverse)
  if (is.character(d_transform)) d_transform <- match.fun(d_transform)
  if (is.character(d_inverse)) d_inverse <- match.fun(d_inverse)

  structure(
    list(
      name = name,
      transform = transform,
      inverse = inverse,
      d_transform = d_transform,
      d_inverse = d_inverse,
      breaks = breaks,
      minor_breaks = minor_breaks,
      format = format,
      domain = domain
    ),
    class = "transform"
  )
}`

const rtdal006533Source0005 = `print.transform <- function(x, ...) {
  cat(
    "Transformer: ",
    x$name,
    " [",
    x$domain[[1]],
    ", ",
    x$domain[[2]],
    "]\n",
    sep = ""
  )
  invisible(x)
}`

const rtdal006533Source0006 = `plot.transform <- function(x, y, ..., xlim, ylim = NULL) {
  if (is.null(ylim)) {
    ylim <- range(
      x$transform(seq(xlim[1], xlim[2], length = 100)),
      finite = TRUE
    )
  }

  plot(
    xlim,
    ylim,
    xlab = "",
    ylab = "",
    type = "n",
    main = paste0("Transformer: ", x$name),
  )

  graphics::grid(lty = "solid")
  graphics::abline(h = 0, v = 0, col = "grey90", lwd = 5)
  graphics::lines(x, xlim = xlim)
}`

const rtdal006533Source0007 = `lines.transform <- function(x, ..., xlim) {
  xgrid <- seq(xlim[1], xlim[2], length = 100)
  y <- suppressWarnings(x$transform(xgrid))

  graphics::lines(xgrid, y, ...)
}`

const rtdal006533Source0008 = "as.transform <- function(x, arg = deparse(substitute(x))) {\n  if (is.transform(x)) {\n    return(x)\n  }\n  if (!(is.character(x) && length(x) >= 1)) {\n    stop_input_type(x, \"a character vector or transform object\")\n  }\n\n  # A character vector is translated to a transform composition\n  if (length(x) != 1) {\n    return(transform_compose(!!!x))\n  }\n\n  # Single characters are interpreted as function names with the\n  # `transform_`-prefix\n  f <- paste0(\"transform_\", x)\n  fun <- get0(f, mode = \"function\")\n\n  # For backward compatibility we preserve `trans_`-prefixes\n  if (is.null(fun)) {\n    f2 <- paste0(x, \"_trans\")\n    fun <- get0(f2, mode = \"function\")\n  }\n\n  if (is.null(fun)) {\n    cli::cli_abort(\n      \"Could not find any function named {.fun {f}} or {.fun {f2}}\"\n    )\n  }\n  fun()\n}"

const rtdal006533Source0010 = `trim_to_domain <- function(transform, x) {
  transform <- as.transform(transform)
  range(transform$transform(range(squish(x, transform$domain), na.rm = TRUE)))
}`

