const rtdal006541Source0001 = `test_that("Special values yield NAs", {
  pal <- seq_gradient_pal()

  expect_equal(pal(NA), NA_character_)
  expect_equal(pal(NaN), NA_character_)
  expect_equal(pal(Inf), NA_character_)
  expect_equal(pal(-Inf), NA_character_)
})`

const rtdal006541Source0002 = `test_that("can make ramp with single color", {
  expect_equal(colour_ramp("black")(0.5), "black")
  expect_equal(colour_ramp("black", na.color = "red")(NA), "red")
})`

const rtdal006541Source0003 = `test_that("Fully opaque colors are returned without alpha", {
  expect_equal(
    colour_ramp(c("#1234AB", "#BA4321"))(0:1),
    c("#1234AB", "#BA4321")
  )
})`

const rtdal006541Source0004 = `test_that("Partially transparent colors are returned with alpha", {
  expect_equal(
    colour_ramp(c("#1234AB20", "#BA43218F"))(0:1),
    c("#1234AB20", "#BA43218F")
  )
})`

