const rtdal006575Source0001 = `jekyll = function(
  dir = '.', input = c('.', '_source', '_posts'), output = c('.', '_posts', '_posts'),
  script = c('Makefile', 'build.R'), serve = TRUE, command = 'jekyll build', ...
) {
  baseurl = jekyll_config(dir, 'baseurl', '')
  destination = jekyll_config(dir, 'destination', '_site')
  jekyll_build = function() {
    if (system(command) != 0) stop('Failed to run: ', command)
  }
  build_all = function() knit_maybe(input, output, script, method = 'jekyll')

  if (!serve) {
    in_dir(dir, {
      build_all()
      jekyll_build()
    })
    return()
  }
  dynamic_site(
    dir, ...,
    build = function(...) {
      update = build_all()
      if (update || !file_test('-d', destination)) jekyll_build()
      update
    },
    site.dir = destination,
    baseurl = baseurl
  )
}`

const rtdal006575Source0002 = `jekyll_config = function(dir, field, default) {
  if (!file.exists(config <- file.path(dir, '_config.yml'))) return(default)
  x = xfun::read_utf8(config)
  p = sprintf('^%s:\\s*([^#[:space:]]+).*$', field)
  x = grep(p, x, value = TRUE)
  if (length(x) == 1) gsub('"', '', sub(p, '\\1', x)) else default
}`

const rtdal006575Source0003 = `rmdv2 = function(dir = '.', script = c('Makefile', 'build.R'), in_session = FALSE, ...) {
  dynamic_rmd(dir, script, ..., method = 'rmdv2', in_session = in_session)
}`

const rtdal006575Source0004 = `rmdv1 = function(dir = '.', script = c('Makefile', 'build.R'), in_session = FALSE, ...) {
  dynamic_rmd(dir, script, ..., method = 'rmdv1', in_session = in_session)
}`

const rtdal006575Source0005 = `dynamic_rmd = function(dir, script, ..., method, in_session = FALSE) {
  dynamic_site(
    dir, ...,
    build = function(message) {
      # exclude .hidden dirs
      dirs = grep('^[.].', list.dirs(), value = TRUE, invert = TRUE)
      knit_maybe(dirs, dirs, script, method, in_session)
    },
    site.dir = '.'
  )
}`

const rtdal006575Source0006 = `dynamic_site = function(
  dir = '.', ..., build = function(...) FALSE, site.dir = dir,
  pre_process = identity, post_process = identity, response = serve_dir(),
  ws_handler = pkg_file('ws-reload.js')
) {
  dir = normalizePath(dir, mustWork = TRUE)
  in_dir(dir, build(NULL))

  res = server_config(dir, ...)
  js = xfun::file_string(ws_handler)

  app = list(
    call = function(req) {
      owd = setwd(dir); on.exit(setwd(owd))
      setwd(site.dir)
      req = pre_process(req)
      ret = response(req)
      req = post_process(req)
      add_js(ret, js, res$interval, req$PATH_INFO)
    },
    onWSOpen = function(ws) {
      ws$onMessage(function(binary, message) in_dir(dir, {
        # send the result of build() to the websocket client
        ws$send(tryCatch(
          toJSON(build(message), auto_unbox = TRUE, null = 'null'),
          error = function(e) { print(e); 'null' }
        ))
      }))
    }
  )
  res$start_server(app)
  invisible(res)
}`

const rtdal006575Source0009 = `add_js = function(res, js, ...) {
  if (res$status != 200L || res$headers[['Content-Type']] != 'text/html')
    return(res)
  # post-process HTML content: inject the websocket code
  body = res$body
  if (is.raw(body)) {
    body = rawToChar(body)
    Encoding(body) = 'UTF-8'
  }
  if (length(grep('<!-- DISABLE-SERVR-WEBSOCKET -->', body, fixed = TRUE)))
    return(res)
  js = ws_js(js, ...)
  body = if (length(grep('</head>', body))) sub(
    '</head>', paste2(js, '</head>'), body, fixed = TRUE
  ) else if (length(grep('</html>', body)) == 0) {
    # there is no </head> or </html>, just append js after the document
    paste2(body, js)
  } else body
  res$body = body
  res
}`

const rtdal006575Source0010 = "knit_maybe = function(input, output, script, method = 'jekyll', in_session = FALSE) {\n  # if the script is a Makefile, check `make -q` to see if we need to\n  # re-generate any files; if we do not, there is nothing to do, otherwise run\n  # make, and tell the client that the files have been updated\n  if (is.character(script)) {\n    if (('Makefile' %in% script) && file.exists('Makefile')) {\n      if (in_session) warning('You cannot use in_session = TRUE with Makefile')\n      return(make_maybe())\n    }\n    script = setdiff(script, 'Makefile')\n    if (length(script) != 1) stop(\"The length of the 'script' argument must be 1\")\n  }\n\n  outext = switch(method, jekyll = '.md', '.html')\n  # check if R Markdown files need to be recompiled\n  res = mapply(\n    obsolete_out, input, output,\n    MoreArgs = list(outext = outext), SIMPLIFY = FALSE\n  )\n  update = FALSE\n  # recompile source documents\n  lapply(res, function(r) {\n    if (length(r) == 0) return()\n    update <<- TRUE\n    # compile each posts in a separate R session\n    for (i in seq_len(nrow(r))) {\n      # run script if exists, passing input and output filenames to Rscript\n      if (!in_session && file.exists(script)) {\n        rscript(shQuote(c(script, r[i, 1], r[i, 2])), r[i, 1])\n        next\n      }\n      if (in_session && is.function(script)) {\n        script(r[i, 1], r[i, 2])\n        next\n      }\n      # otherwise run default code\n      build = getFromNamespace(paste('build', method, sep = '_'), 'servr')\n      build(r[i, 1], r[i, 2], in_session)\n    }\n    if (any(i <- !file.exists(r[, 2])))\n      stop('Some output files were not successfully generated: ', paste(r[i, 2], collapse = ', '))\n  })\n  update\n}"

const rtdal006575Source0012 = `build_jekyll = function(input, output, ...) {
  code = c(
    sprintf(
      c("knitr::opts_chunk$set(fig.path = 'figure/%s/', ",
        "cache.path = 'cache/%s/')"),
      gsub('^_|[.][a-zA-Z]+$', '', input)
    ),
    "knitr::opts_knit$set(base.url = '/')",
    sprintf("knitr::knit('%s', '%s', quiet = TRUE)", input, output)
  )
  rscript(c(rbind('-e', shQuote(code))), input)
}`

const rtdal006575Source0013 = `build_rmd = function(input, output, template, in_session) {
  owd = setwd(dirname(input)); on.exit(setwd(owd))
  input = basename(input)
  code = sprintf(template, input)
  if (in_session) {
    eval(parse(text = code), envir = globalenv())
  } else {
    rscript(c(rbind('-e', shQuote(code))), file.path(owd, input))
  }
}`

const rtdal006575Source0014 = `build_rmdv2 = function(...) {
  build_rmd(..., template = "rmarkdown::render('%s', quiet = TRUE)")
}`

const rtdal006575Source0015 = `build_rmdv1 = function(...) {
  build_rmd(..., template = "knitr::knit2html('%s', quiet = TRUE)")
}`

