const rtdal006595Source0003 = `st_agr = function(x, ...) UseMethod("st_agr")`

const rtdal006595Source0004 = `st_agr.sf = function(x, ...) {
	sfc_s = sapply(x, inherits, "sfc")
	nm = names(x)[!sfc_s]
	ret = attr(x, "agr")[nm]
	if (is.null(names(ret)) || all(is.na(names(ret))))
		structure(rep(NA_agr_, length(nm)), names = nm)
	else
		ret
}`

const rtdal006595Source0005 = `st_agr.character = function(x, ...) {
	structure(factor(x, levels = agr_levels), names = names(x))
}`

const rtdal006595Source0006 = `st_agr.factor = function(x, ...) {
	stopifnot(all(levels(x) == agr_levels))
	x
}`

const rtdal006595Source0007 = `st_agr.default = function(x = NA_character_, ...) {
	if (is.data.frame(x) && !is.null(attr(x, "agr")))
		x = attr(x, "agr")
	structure(st_agr(as.character(x)), names = names(x))
}`

