const rtdal006604Source0001 = `Ops.crs <- function(e1, e2) {
	if (nargs() == 1)
		stop(paste("unary", .Generic, "not defined for \"crs\" objects"), call. = FALSE)

	cmp <- switch(.Generic, "==" =, "!=" = TRUE, FALSE)
	if (!cmp)
		stop(paste("operation", .Generic, "not supported for crs objects"), call. = FALSE)
	if (.Generic == "!=")
		!(e1 == e2)
	else { # "==": check semantic equality
		if (isTRUE(all.equal(e1, e2))) # includes both are NA_crs_
			TRUE
		else if (is.na(e1) || is.na(e2)) # only one of them is NA_crs_
			FALSE
		else
			isTRUE(try(CPL_crs_equivalent(e1, e2), silent = TRUE)) # use GDAL's srs1->IsSame(srs2)
	}
}`

const rtdal006604Source0002 = `st_crs = function(x, ...) UseMethod("st_crs")`

const rtdal006604Source0003 = `st_crs.sf = function(x, ...) st_crs(st_geometry(x), ...)`

const rtdal006604Source0004 = `st_crs.numeric = function(x, ...) {
	if (!is.finite(x))
		NA_crs_
	else
    	make_crs(paste0("EPSG:", x))
}`

const rtdal006604Source0005 = `st_crs.character = function(x, ...) {
	if (is.na(x))
		NA_crs_
	else {
		crs = make_crs(x)
		if (is.na(crs))
			stop(paste("invalid crs:", x))
		# if we input wkt2, and CRS has a name, use it:
		if (identical(x, crs$wkt) && !identical(crs$Name, "unknown"))
			crs$input = crs$Name
		crs
	}
}`

const rtdal006604Source0006 = `fix_crs = function(x) {
	if (all(c("epsg", "proj4string") %in% names(x))) {
		message("old-style crs object detected; please recreate object with a recent sf::st_crs()")
		x = unclass(x)
		if (!is.na(x$epsg))
			st_crs(x$epsg)
		else
			st_crs(x$proj4string)
	} else
		x
}`

const rtdal006604Source0007 = `st_crs.sfc = function(x, ..., parameters = FALSE) {
	crs = fix_crs(attr(x, "crs"))
	if (isTRUE(parameters)) {
		p = crs_parameters(crs)
		p$ud_unit = crs_ud_unit(crs)
		p
	} else
		crs
}`

const rtdal006604Source0008 = `st_crs.bbox = function(x, ...) {
	crs = attr(x, "crs")
	if (is.null(crs))
		NA_crs_
	else
		crs
}`

const rtdal006604Source0009 = `st_crs.CRS = function(x, ...) {
	if (is.null(comment(x)) || CPL_proj_version() < "6.0.0" || 
			CPL_gdal_version() < "3.0.0")
		st_crs(x@projargs)
	else {
		ret = st_crs(comment(x))
		name = ret$Name
		ret$input = if (name == "unknown")
				x@projargs
			else
				name
		ret
	}
}`

const rtdal006604Source0010 = `st_crs.crs = function(x, ...) x`

const rtdal006604Source0011 = `st_crs.default = function(x, ...) NA_crs_`

const rtdal006604Source0013 = "`st_crs<-.sf` = function(x, value) {\n\tst_crs(x[[ attr(x, \"sf_column\") ]]) = value\n\tx\n}"

const rtdal006604Source0014 = `make_crs = function(x) {

	if (inherits(x, "CRS")) {
		x = if (is.null(comment(x)) || (CPL_proj_version() < "6.0.0" || 
                    CPL_gdal_version() < "3.0.0"))

				x@projargs
			else
				comment(x) # WKT2
	}
	if (is.numeric(x) && !is.na(x))
		x = paste0("EPSG:", x)
	# return:
	if (is.na(x))
		NA_crs_
	else if (inherits(x, "crs"))
		x
	else if (is.character(x)) {
		if (grepl("+init=epsg:", x) &&
				compareVersion(sf_extSoftVersion()[["proj.4"]], "6.0.0") >= 0 &&
				compareVersion(sf_extSoftVersion()[["proj.4"]], "6.3.1") < 0) { # nocov start FIXME:
			x = strsplit(x, " ")[[1]]
			if (length(x) > 1)
				warning(paste("the following proj4string elements are ignored:",
					paste(x[-1], collapse = " "), "; remove the +init=epsg:XXXX to undo this"))
			x = paste0("EPSG:", as.integer(substr(x[1], 12, 20))) # nocov end
		}
		CPL_crs_from_input(x)
	} else
		stop(paste("cannot create a crs from an object of class", class(x)), call. = FALSE)
}`

const rtdal006604Source0017 = `st_set_crs = function(x, value) {
	st_crs(x) = value
	x
}`

const rtdal006604Source0018 = `st_is_longlat = function(x) {
	crs = st_crs(x)
	if (is.na(crs))
		NA
	else {
		ret = crs_parameters(crs)$IsGeographic
		if (ret && inherits(x, c("sf", "sfc", "stars")) && !is.null(attr(x, "bbox"))) {
			bb = st_bbox(x)
			# check for potentially meaningless value range:
			eps = sqrt(.Machine$double.eps)
			if (all(!is.na(unclass(bb))) &&
					(bb["xmin"] < (-180-eps) || bb["xmax"] > (360+eps) || bb["ymin"] < (-90-eps) || bb["ymax"] > (90+eps)))
				warning("bounding box has potentially an invalid value range for longlat data")
		}
		ret
	}
}`

const rtdal006604Source0020 = `crs_ud_unit = function(x) {
	stopifnot(inherits(x, "crs"))
	if (is.na(x))
		return(NULL)

	x = crs_parameters(x)
	if (!is.null(x$units_gdal)) {
		u = udunits_from_proj[[x$units_gdal]]
		if (is.null(u)) {
			u = try(as_units(x$units_gdal), silent = TRUE)
			if (inherits(u, "try-error"))
				u = NULL
		}
		u
	} else
		NULL #2049
}`

const rtdal006604Source0021 = `crs_parameters = function(x) {
	stopifnot(inherits(x, "crs"))
	if (is.na(x))
		list()
	else {
		ret = CPL_crs_parameters(x)
		units(ret$SemiMajor) = as_units("m")
		units(ret$SemiMinor) = as_units("m")
		ret
	}
}`

const rtdal006604Source0024 = `st_as_text.crs = function(x, ..., projjson = FALSE, pretty = FALSE) {
	if (is.na(x))
		NA_character_
	else if (projjson) {
		if (compareVersion(sf_extSoftVersion()["GDAL"], "3.1.0") == -1 || compareVersion(sf_extSoftVersion()["proj.4"], "6.2.0") == -1)
			stop("ProjJson requires GDAL >= 3.1.0 and PROJ >= 6.2.0")
		crs_parameters(x)$ProjJson
	} else { # wkt:
		if (pretty)
			crs_parameters(x)$WktPretty
		else
			crs_parameters(x)$Wkt
	}
}`

const rtdal006604Source0027 = "`$.crs` = function(x, name) {\n\n\tif (!is.null(x[[\"proj4string\"]])) { # old-style object:\n\t\twarning(\"CRS uses proj4string, which is deprecated.\")\n\t\tx = st_crs(x[[\"proj4string\"]]) # FIXME: should this be only for some transition period? Add test?\n\t}\n\tif (name == \"ud_unit\")\n\t\tcrs_ud_unit(x)\n\telse if (is.na(x))\n\t\tNA_character_\n\telse if (is.numeric(name) || name %in% names(x))\n\t\tx[[name]]\n\telse {\n\t\tp = crs_parameters(x)\n\t\tif (name %in% names(p))\n\t\t\tp[[name]]\n\t\telse {\n\t\t\ttryNum = function(x) { n = suppressWarnings(as.numeric(x)); if (is.na(n)) x else n }\n\t\t\tp4s = strsplit(p$proj4string, \" \")[[1]]\n\t\t\tp4s2 = strsplit(p4s, \"=\")\n\t\t\tvals = lapply(p4s2, function(x) if (length(x) == 1) TRUE else tryNum(x[2]))\n\t\t\tnames(vals) = substring(sapply(p4s2, function(x) x[1]), 2)\n\t\t\tvals[[name]]\n\t\t}\n\t}\n}"

const rtdal006604Source0028 = `print.crs = function(x, ...) {
  cat("Coordinate Reference System:")
  if (is.na(x)) {
    cat(" NA\n")
  } else {
    cat("\n")
    if (is.na(x$input))
       cat("  No user input\n")
    else
       cat("  User input:", x$input, "\n")

	# print wkt:
    if (!is.na(x$wkt))
      cat("  wkt:\n", x$wkt, "\n", sep = "")
  }
}`

const rtdal006604Source0029 = `format.crs = function(x, ...) {
	if (is.na(x))
		NA_character_
	else {
		p = crs_parameters(x)
		if (p$Name == "unknown") {
			if (x$input == "unknown")
				x$proj4string
			else
				x$input
		} else
			x$Name
	}
}`

const rtdal006604Source0030 = `st_crs.Raster = function(x, ...) {
	crsobj <- raster::crs(x)
	st_crs(crsobj) # nocov
}`

const rtdal006604Source0031 = `st_crs.Spatial = function(x, ...) {
	if (! requireNamespace("sp", quietly = TRUE))
		stop("package sp required, please install it first")
	st_crs(x@proj4string) # nocov
}`

