const rtdal006611Source0093 = `st_snap.sfc = function(x, y, tolerance) {
	if (isTRUE(st_is_longlat(x)))
		stop("st_snap for longitude/latitude data not supported; use st_transform first?")
	else if (inherits(tolerance, "units") && !is.null(st_crs(x)$ud_unit))
		units(tolerance) = st_crs(x)$ud_unit # coordinate units
	tolerance = rep(tolerance, length.out = length(x))
	st_sfc(CPL_geos_snap(st_geometry(x), st_geometry(y), as.double(tolerance)))
}`

const rtdal006611Source0095 = `st_union = function(x, y, ..., by_feature = FALSE, is_coverage = FALSE) UseMethod("st_union")`

const rtdal006611Source0096 = `st_union.sfg = function(x, y, ..., by_feature = FALSE, is_coverage = FALSE) {
	out = if (missing(y)) # unary union, possibly by_feature:
		st_sfc(CPL_geos_union(st_geometry(x), by_feature, is_coverage))
	else
		st_union(st_geometry(x), st_geometry(y))
	get_first_sfg(out)
}`

const rtdal006611Source0097 = `st_union.sfc = function(x, y, ..., by_feature = isTRUE(list(...)$by_element), is_coverage = FALSE) {
	ll = isTRUE(st_is_longlat(x))
	if (missing(y)) { # unary union, possibly by_feature:
		if (ll && sf_use_s2()) { 
			if (! by_feature) { # see https://github.com/r-spatial/s2/issues/97 :
				if (is_coverage)
					st_as_sfc(s2::s2_coverage_union_agg(x, ...), crs = st_crs(x))
				else
					st_as_sfc(s2::s2_union_agg(x, ...), crs = st_crs(x)) 
			} else
				st_as_sfc(s2::s2_union(x, ...), crs = st_crs(x)) 
		} else {
			if (ll)
				message_longlat("st_union")
			st_sfc(CPL_geos_union(x, by_feature, is_coverage))
		}
	} else {
		y = st_geometry(y)
		stopifnot(st_crs(x) == st_crs(y))
		if (is_coverage)
			message("in st_union(), is_coverage is ignored when y is given")
		if (by_feature)
			stopifnot(length(x) == length(y))
		if (ll && sf_use_s2()) {
			if (by_feature)
				st_as_sfc(s2::s2_union(x, y, ...), crs = st_crs(x)) 
			else {
				i = rep(seq_along(x), each = length(y))
				j = rep(seq_along(y), length(x))
				st_as_sfc(s2::s2_union(x[i], y[j], ...), crs = st_crs(x), precision = st_precision(x)) 
			}
		} else {
			if (ll)
				message_longlat("st_union")
			if (by_feature) # old-style: in case by_element is not specified
				geos_op2_geom("union", x, y, by_element = TRUE, ...)
			else
				geos_op2_geom("union", x, y, ...) # handles by_element
		}
	}
}`

const rtdal006611Source0098 = `st_union.sf = function(x, y, ..., by_feature = FALSE, is_coverage = FALSE) {
	if (missing(y)) { # unary union, possibly by_feature:
		geom = st_union(st_geometry(x), ..., by_feature = by_feature, is_coverage = is_coverage)
		if (by_feature)
			st_set_geometry(x, geom)
		else
			geom
	} else {
		if (by_feature) {
			df = cbind(st_drop_geometry(x), st_drop_geometry(y))
			st_set_geometry(df, st_union(st_geometry(x), st_geometry(y), is_coverage = is_coverage))
		} else
			geos_op2_df(x, y, geos_op2_geom("union", x, y, ...))
	}
}`

const rtdal006611Source0099 = `st_line_sample = function(x, n, density, type = "regular", sample = NULL) {
	if (isTRUE(st_is_longlat(x)))
		stop("st_line_sample for longitude/latitude not supported; use st_segmentize?")
	l = st_length(x)
	distList = if (is.null(sample)) {
		n = if (missing(n)) {
			if (!is.null(st_crs(x)$ud_unit) && inherits(density, "units"))
				units(density) = 1/st_crs(x)$ud_unit # coordinate units
			round(rep(density, length.out = length(l)) * l)
		} else
			rep(n, length.out = length(l))
		regular = function(n) { (seq_len(n) - 0.5)/n }
		random = function(n) { sort(runif(n)) }
		fn = switch(type,
					regular = regular,
					random = random,
					stop("unknown type"))
		lapply(seq_along(n), function(i) fn(n[i]) * l[i])
	} else
		lapply(seq_along(l), function(i) sample * l[i])

	x = st_geometry(x)
	stopifnot(inherits(x, "sfc_LINESTRING"))
	st_sfc(CPL_gdal_linestring_sample(x, distList), crs = st_crs(x))
}`

const rtdal006611Source0101 = `st_line_interpolate = function(line, dist, normalized = FALSE) {
	stopifnot(inherits(line, "sfc"), all(st_dimension(line) == 1), 
		is.logical(normalized), length(normalized) == 1,
		is.numeric(dist))
	if (isTRUE(st_is_longlat(line))) {
		message_longlat("st_project_point")
		if (inherits(dist, "units"))
			dist = units::set_units(dist, "degree", mode = "standard")
		else
			stop("for interpolating geographic coordinates, dist should have units degree; see examples")
	}
	line = st_cast(line, "LINESTRING")
	recycled = recycle_common(list(line, dist))
	st_sfc(CPL_line_interpolate(recycled[[1]], recycled[[2]], normalized), 
		   crs = st_crs(line))
}`

const rtdal006611Source0102 = `st_exterior_ring = function(x, ...) UseMethod("st_exterior_ring")`

const rtdal006611Source0103 = `st_exterior_ring.sf = function(x, ...)
	st_set_geometry(x, st_exterior_ring(st_geometry(x)))`

const rtdal006611Source0104 = `st_exterior_ring.sfg = function(x, ...)
	st_exterior_ring(st_sfc(x))[[1]]`

const rtdal006611Source0105 = `st_exterior_ring.sfc = function(x, ...) {
	stopifnot(all(st_dimension(x, NA_if_empty = FALSE) == 2))
	exterior_sfg = function(x) {
		if (inherits(x, "MULTIPOLYGON"))
			st_multipolygon(lapply(st_cast(st_sfc(x), "POLYGON"), exterior_sfg))
		else if (inherits(x, "POLYGON"))
			st_polygon(x[1])
		else
			stop(paste("no exterior_ring method for objects of class", class(x)[1]))
	}
	st_as_sfc(lapply(x, exterior_sfg), crs = st_crs(x))
}`

