const rtdal006614Source0001 = `st_as_grob = function(x, ...) UseMethod("st_as_grob")`

const rtdal006614Source0002 = `st_as_grob.POINT = function(x, pch = 1, size = unit(1, "char"), default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (anyNA(x))
		nullGrob()
	else
		pointsGrob(x[1], x[2], pch = pch, size = size, default.units = default.units, name = name, gp = gp, vp = vp)
}`

const rtdal006614Source0003 = `st_as_grob.MULTIPOINT = function(x, pch = 1, size = unit(1, "char"), default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (nrow(x) == 0)
		nullGrob()
	else
		pointsGrob(x[,1], x[,2], pch = pch, size = size, default.units = default.units, name = name, gp = gp, vp = vp)
}`

const rtdal006614Source0004 = `st_as_grob.LINESTRING = function(x, arrow = NULL, default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (nrow(x) == 0)
		nullGrob()
	else
		linesGrob(x[,1], x[,2], arrow = NULL, default.units = default.units, name = name, gp = gp, vp = vp)
}`

const rtdal006614Source0005 = `st_as_grob.CIRCULARSTRING = function(x, y, ...) {
	st_as_grob(st_cast(x, "LINESTRING"),  ...)
}`

const rtdal006614Source0006 = `st_as_grob.MULTILINESTRING = function(x, arrow = NULL, default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (length(x) == 0)
		nullGrob()
	else {
		get_x = function(x) unlist(sapply(x, function(y) y[,1]))
		get_y = function(x) unlist(sapply(x, function(y) y[,2]))
		polylineGrob(get_x(x), get_y(x), id.lengths = vapply(x, nrow, 0L), arrow = NULL,
			default.units = default.units, name = name, gp = gp, vp = vp)
	}
}`

const rtdal006614Source0007 = `st_as_grob.POLYGON = function(x, default.units = "native", rule = "evenodd", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (length(x) == 0)
		nullGrob()
	else {
		get_x = function(x) unlist(sapply(x, function(y) y[,1]))
		get_y = function(x) unlist(sapply(x, function(y) y[,2]))
		pathGrob(get_x(x), get_y(x), id.lengths = vapply(x, nrow, 0L), default.units = default.units, rule = rule, name = name, gp = gp, vp = vp)
	}
}`

const rtdal006614Source0008 = `st_as_grob.MULTIPOLYGON = function(x, default.units = "native", rule = "evenodd", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (length(x) == 0)
		nullGrob()
	else {
		get_x = function(x) unlist(sapply(x, function(y) sapply(y, function(z) z[,1])))
		get_y = function(x) unlist(sapply(x, function(y) sapply(y, function(z) z[,2])))
		get_l = function(x) unlist(sapply(x, function(y) vapply(y, nrow, 0L)))
		pathGrob(get_x(x), get_y(x), id.lengths = get_l(x), default.units = default.units, rule = rule, name = name, gp = gp, vp = vp)
	}
}`

const rtdal006614Source0009 = `st_as_grob.GEOMETRYCOLLECTION = function(x, ...) {
	if (length(x) == 0)
		nullGrob()
	else
		do.call(grid::grobTree, lapply(x, st_as_grob, ...))
}`

const rtdal006614Source0013 = `st_viewport = function(x, ..., bbox = st_bbox(x), asp) {
	xscale = bbox[c(1,3)]
	yscale = bbox[c(2,4)]

	# from rgdal2/R/graphics.R:
	current.viewport.size = function(units = "inches") {
    	vp = current.viewport()
		vi = convertHeight(vp$height, units, valueOnly = TRUE)
		wi = convertWidth(vp$width, units, valueOnly = TRUE)
    	c(width = wi, height = vi)
	}
	current.viewport.aspect = function() {
    	sz = current.viewport.size()
    	sz[2] / sz[1]
	}
	vp.asp = current.viewport.aspect()
	if (missing(asp))
		asp = if (isTRUE(st_is_longlat(x)))
			1.0 / cos((mean(yscale) * pi)/180)
		else
			1.0

   	obj.asp = asp * diff(yscale) / diff(xscale)
	height = obj.asp / vp.asp
   	width = 1
   	width = width / max(width, height)
   	height = height / max(width, height)
	viewport(width = unit(width, "npc"), height = unit(height, "npc"),
    		xscale = unit(xscale, "native"), yscale = unit(yscale, "native"), ...)
}`

const rtdal006614Source0014 = `st_as_grob.sfc_POINT <- function(x, pch = 1, size = unit(1, "char"), default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (any(is_e <- st_is_empty(x))) {
		gp = gp[!is_e]
		x = x[!is_e]
	}
	if (length(x)) {
		x <- matrix(unlist(x, use.names = FALSE), ncol = length(x))
		pointsGrob(x[1, ], x[2, ], pch = pch, size = size,
				   default.units = default.units, name = name, gp = gp, vp = vp)
	} else
		nullGrob()
}`

const rtdal006614Source0015 = `st_as_grob.sfc_MULTIPOINT <- function(x, pch = 1, size = unit(1, "char"), default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (any(is_e <- st_is_empty(x))) {
		gp = gp[!is_e]
		x = x[!is_e]
	}
	if (length(x)) {
		x <- unclass(x)
		n_points <- vapply(x, nrow, integer(1))
		gp <- expand_gp(gp, n_points)
		if (length(pch) != 1) pch <- rep(rep(pch, length.out = length(x)), n_points)
		if (length(size) != 1) size <- rep(rep(size, length.out = length(x)), n_points)
		x <- do.call(rbind, x)
		pointsGrob(x[, 1], x[, 2], pch = pch, size = size, 
				   default.units = default.units, name = name, gp = gp, vp = vp)
	} else
		nullGrob()
}`

const rtdal006614Source0016 = `st_as_grob.sfc_LINESTRING <- function(x, arrow = NULL, default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (any(is_e <- st_is_empty(x))) {
		gp = gp[!is_e]
		x = x[!is_e]
	}
	if (length(x)) {
		x <- unclass(x)
		n_points <- vapply(x, nrow, integer(1))
		x <- do.call(rbind, x)
		polylineGrob(x[, 1], x[, 2], id.lengths = n_points, arrow = arrow, 
					 default.units = default.units, name = name, gp = gp, vp = vp)
	} else
		nullGrob()
}`

const rtdal006614Source0017 = `st_as_grob.sfc_MULTILINESTRING <- function(x, arrow = NULL, default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (any(is_e <- st_is_empty(x))) {
		gp = gp[!is_e]
		x = x[!is_e]
	}
	if (length(x)) {
		x <- unclass(x)
		n_lines <- vapply(x, length, integer(1))
		gp <- expand_gp(gp, n_lines)
		if (!is.null(arrow) && length(arrow) != 1) arrow <- rep(rep(arrow, length.out = length(x)), n_lines)
		x <- unlist(x, recursive = FALSE)
		n_points <- vapply(x, nrow, integer(1))
		x <- do.call(rbind, x)
		polylineGrob(x[, 1], x[, 2], id.lengths = n_points, arrow = arrow, 
					 default.units = default.units, name = name, gp = gp, vp = vp)
	} else
		nullGrob()
}`

const rtdal006614Source0018 = `st_as_grob.sfc_POLYGON <- function(x, rule = "evenodd", default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (utils::packageVersion("grid") < "3.6") {
		return(scalar_grobs(x, rule = rule, default.units = default.units, name = name, gp = gp, vp = vp, ...)) # nocov
	}
	if (any(is_e <- st_is_empty(x))) {
		gp = gp[!is_e]
		x = x[!is_e]
	}
	if (length(x)) {
		x <- unclass(x) # nocov start
		n_poly <- vapply(x, length, integer(1))
		x <- unlist(x, recursive = FALSE)
		n_points <- vapply(x, nrow, integer(1))
		n_paths <- tapply(n_points, rep(seq_along(n_poly), n_poly), sum)
		x <- do.call(rbind, x)
		pathGrob(x[, 1], x[, 2], id.lengths = n_points, pathId.lengths = n_paths, 
				 rule = rule, default.units = default.units, name = name, gp = gp, vp = vp) # nocov end
	} else
		nullGrob()
}`

const rtdal006614Source0019 = `st_as_grob.sfc_MULTIPOLYGON <- function(x, rule = "evenodd", default.units = "native", name = NULL, gp = gpar(), vp = NULL, ...) {
	if (utils::packageVersion("grid") < "3.6") {
		return(scalar_grobs(x, rule = rule, default.units = default.units, name = name, gp = gp, vp = vp, ...)) # nocov
	}
	if (any(is_e <- st_is_empty(x))) {
		gp = gp[!is_e]
		x = x[!is_e]
	}
	if (length(x)) {
		x <- unclass(x) # nocov start
		n_poly <- vapply(x, length, integer(1))
		gp <- expand_gp(gp, n_poly)
		x <- unlist(x, recursive = FALSE)
		n_poly <- vapply(x, length, integer(1))
		x <- unlist(x, recursive = FALSE)
		n_points <- vapply(x, nrow, integer(1))
		n_paths <- tapply(n_points, rep(seq_along(n_poly), n_poly), sum)
		x <- do.call(rbind, x)
		pathGrob(x[, 1], x[, 2], id.lengths = n_points, pathId.lengths = n_paths, 
				 rule = rule, default.units = default.units, name = name, gp = gp, vp = vp) # nocov end
	} else
		nullGrob()
}`

const rtdal006614Source0020 = `st_as_grob.sfc_CIRCULARSTRING <- function(x, ...) {
	st_as_grob(st_cast(x, 'LINESTRING'), ...) # nocov
}`

const rtdal006614Source0021 = `st_as_grob.sfc <- function(x, pch = 1, size = unit(1, "char"), arrow = NULL, gp = gpar(), ...) {
	old_length <- length(x)
	x <- st_cast_sfc_default(x)
	ids <- attr(x, 'ids')
	if (!is.null(ids)) {
		# x was a geometrycollection that has been unlisted. Need to match gpar
		if (length(pch) > 1) {
			pch <- rep(rep_len(pch, old_length), ids)
		}
		if (length(size) > 1) {
			size <- rep(rep_len(size, old_length), ids)
		}
		if (length(arrow) > 1) {
			arrow <- rep(rep_len(arrow, old_length), ids)
		}
		for (par in names(gp)) {
			if (length(gp[[par]]) > 1) {
				gp[[par]] <- rep(rep_len(gp[[par]], old_length), ids)
			}
		}
	}
	if (class(x)[1] %in% c('sfc_MULTIPOINT', 'sfc_MULTILINESTRING', 'sfc_MULTIPOLYGON'))
		st_as_grob(x, pch = pch, size = size, arrow = arrow, gp = gp, ...)
	else
		scalar_grobs(x, pch, size, arrow, gp, ...)
}`

const rtdal006614Source0022 = `scalar_grobs <- function(x, pch = 1, size = unit(1, "char"), arrow = NULL, gp = gpar(), ...) {
	gp <- split_gp(gp, length(x))
	pch <- rep(pch, length.out = length(x))
	size <- rep(size,  length.out = length(x))
	if (!is.null(arrow)) arrow <- rep(arrow, length.out = length(x))
	do.call(gList, lapply(seq_along(x), function(i) {
		st_as_grob(x[[i]], pch = pch[i], size = size[i], arrow = arrow[i], gp = gp[[i]], ...)
	}))
}`

