const rtdal006621Source0004 = `st_as_sf.map = function(x, ..., fill = TRUE, group = TRUE) {
	ID = if (group)
			vapply(strsplit(x$names, ":"), function(y) y[1], "")
		else 
			x$names
	xyList <- NAmat2xyList(cbind(x$x, x$y))
	geom = if (fill)
			map2pol(xyList, ID)
		else
			map2lin(xyList, ID)
	ID = unique(ID)
	stopifnot(length(ID) == length(geom))
	st_sf(ID = ID, geom = geom, crs = "+proj=longlat +ellps=clrk66 +no_defs +type=crs", row.names = ID)
}`

const rtdal006621Source0005 = `st_as_sfc.map = function(x, ...) {
	st_geometry(st_as_sf(x, ...))
}`

