const rtdal006627Source0002 = `set_utf8 = function(x) {
	n = names(x)
	Encoding(n) = "UTF-8"
	to_utf8 = function(x) {
		if (is.character(x))
			Encoding(x) = "UTF-8"
		x
	}
	structure(lapply(x, to_utf8), names = n)
}`

const rtdal006627Source0003 = `st_read = function(dsn, layer, ...) UseMethod("st_read")`

const rtdal006627Source0004 = `st_read.default = function(dsn, layer, ...) {
	if (missing(dsn))
		stop("dsn should specify a data source or filename")
	else {
		dsn_is_null = is.null(dsn)
		class_dsn = class(dsn)
		tr <- try(dsn <- as.character(dsn))
		if (dsn_is_null || inherits(tr, "try-error"))
			stop(paste("no st_read method available for objects of class", paste(class_dsn, collapse = ", ")))
		else
			st_read.character(dsn, layer, ...)
	}
}`

const rtdal006627Source0005 = "process_cpl_read_ogr = function(x, quiet = FALSE, ..., check_ring_dir = FALSE,\n\t\tstringsAsFactors = ifelse(as_tibble, FALSE, sf_stringsAsFactors()),\n\t\tgeometry_column = 1, as_tibble = FALSE, optional = FALSE) {\n\n\twhich.geom = which(vapply(x, function(f) inherits(f, \"sfc\"), TRUE))\n\n\tif (as_tibble && !requireNamespace(\"tibble\", quietly = TRUE))\n\t\tstop(\"package tibble not available: install first?\")\n\n\t# in case no geometry is present:\n\tif (length(which.geom) == 0) {\n\t\tif (! quiet)\n\t\t\twarning(\"no simple feature geometries present: returning a data.frame or tbl_df\", call. = FALSE)\n\t\tx = if (!as_tibble) {\n\t\t\t\tif (any(sapply(x, is.list)))\n\t\t\t\t\twarning(\"list-column(s) present: in case of failure, try read_sf() or as_tibble=TRUE\") # nocov\n\t\t\t\tas.data.frame(x , stringsAsFactors = stringsAsFactors, optional = optional)\n\t\t\t} else\n\t\t\t\ttibble::as_tibble(x)\n\t\treturn(x)\n\t}\n\n\tnm = names(x)[which.geom]\n\tEncoding(nm) = \"UTF-8\"\n\tgeom = x[which.geom]\n\n\tlc.other = setdiff(which(vapply(x, is.list, TRUE)), which.geom) # non-sfc list-columns\n\tlist.cols = x[lc.other]\n\tnm.lc = names(x)[lc.other]\n\n\tif (length(x) == length(geom)) { # ONLY geometry column(s)\n\t\tif (as_tibble)\n\t\t\tx <- tibble::tibble(row.names = seq_along(geom[[1]]))[-1]\n\t\telse\n\t\t\tx <- data.frame(row.names = seq_along(geom[[1]]))\n\t} else {\n\t\tx <- as.data.frame(set_utf8(x[-c(lc.other, which.geom)]), stringsAsFactors = stringsAsFactors,\n\t\t\toptional = optional || as_tibble)\n\t\tif (as_tibble) {\n\t\t\t# \"sf\" class is added later by `st_as_sf` (and sets all the attributes)\n\t\t\tx <- tibble::new_tibble(x, nrow = nrow(x))\n\t\t}\n\t}\n\n\tfor (i in seq_along(lc.other))\n\t\tx[[ nm.lc[i] ]] = list.cols[[i]]\n\n\tfor (i in seq_along(geom)) {\n\t\tif (is.null(attr(geom[[i]], \"bbox\"))) {\n\t\t\tx[[ nm[i] ]] = st_sfc(geom[[i]], crs = attr(geom[[i]], \"crs\")) # computes bbox\n\t\t} else {\n\t\t\tx[[ nm[i] ]] = geom[[i]]\n\t\t}\n\t}\n\n\tx = st_as_sf(x, ...,\n\t\tsf_column_name = if (is.character(geometry_column)) geometry_column else nm[geometry_column],\n\t\tcheck_ring_dir = check_ring_dir)\n\tif (! quiet)\n\t\tprint(x, n = 0)\n\telse\n\t\tx\n}"

const rtdal006627Source0007 = `process_cpl_read_ogr_stream = function(x, geom_column_info, num_features, fid_column_name,
                                       crs = NULL, promote_to_multi = TRUE, ...) {
	is_geometry_column = vapply(
		x$get_schema()$children,
		function(s) identical(s$metadata[["ARROW:extension:name"]], "ogc.wkb"),
		logical(1)
	)
    
    geom_column_info$index = which(is_geometry_column)
    
    if (num_features == -1) {
		num_features = NULL
	}
    
    # Suppress warnings about extension type conversion (since we want the
    # default behaviour of converting the storage type)
	df = suppressWarnings(nanoarrow::convert_array_stream(x, size = num_features))
	
	for (i in seq_len(nrow(geom_column_info))) {
		crs = if (is.null(crs)) st_crs(geom_column_info$crs[[i]]) else st_crs(crs)
		name = geom_column_info$name[[i]]
		index = geom_column_info$index[[i]]
		
		column_wkb = df[[index]]
		attributes(column_wkb) = NULL
		column_sfc = wk::wk_handle(
			wk::new_wk_wkb(column_wkb),
			wk::sfc_writer(promote_multi = promote_to_multi)
		)
		
		df[[index]] = st_set_crs(column_sfc, crs)
		names(df)[index] = name
	}
	
	# Rename OGC_FID to fid_column_name and move to end
	if (length(fid_column_name) == 1 && "OGC_FID" %in% names(df)) {
		df = df[c(setdiff(names(df), "OGC_FID"), "OGC_FID")]
		names(df)[names(df) == "OGC_FID"] = fid_column_name
	}
	
	# All geometry columns to the end
	df = df[c(setdiff(seq_along(df), geom_column_info$index), geom_column_info$index)]
	
	process_cpl_read_ogr(df, ...)
}`

const rtdal006627Source0008 = "st_read.character = function(dsn, layer, ..., query = NA, options = NULL, quiet = FALSE, geometry_column = 1L,\n\t\ttype = 0, promote_to_multi = TRUE, stringsAsFactors = sf_stringsAsFactors(),\n\t\tint64_as_string = FALSE, check_ring_dir = FALSE, fid_column_name = character(0),\n\t\tdrivers = character(0), wkt_filter = character(0), optional = FALSE,\n\t\tuse_stream = default_st_read_use_stream()) {\n\n\tlayer = if (missing(layer))\n\t\tcharacter(0)\n\telse\n\t\tenc2utf8(layer)\n\tif (nchar(dsn) < 1)\n\t\tstop(\"`dsn` must point to a source, not an empty string.\", call. = FALSE)\n\tdsn_exists = file.exists(dsn)\n\tdsn_isdb = is_db_driver(dsn)\n\tif (length(dsn) == 1 && dsn_exists && !dsn_isdb)\n\t\tdsn = enc2utf8(normalizePath(dsn))\n\n\tif (length(promote_to_multi) > 1)\n\t\tstop(\"`promote_to_multi' should have length one, and applies to all geometry columns\")\n\n\tif (use_stream) {\n\t\tstream = nanoarrow::nanoarrow_allocate_array_stream()\n\t\tinfo = CPL_read_gdal_stream(stream, dsn, layer, query, as.character(options), quiet,\n\t\t    drivers, wkt_filter, dsn_exists, dsn_isdb, fid_column_name, getOption(\"width\"))\n\t\tgeom_column_info = data.frame(name = info[[1]], crs = info[[2]], stringsAsFactors = FALSE)\n\t\tprocess_cpl_read_ogr_stream(stream, geom_column_info, num_features = info[[3]],\n\t\t\tfid_column_name = fid_column_name, stringsAsFactors = stringsAsFactors, quiet = quiet,\n\t\t\tpromote_to_multi = promote_to_multi, ...)\n\t} else {\n\t\tx = CPL_read_ogr(dsn, layer, query, as.character(options), quiet, type, fid_column_name,\n\t\t    drivers, wkt_filter, promote_to_multi, int64_as_string, dsn_exists, dsn_isdb, getOption(\"width\"))\n\n        process_cpl_read_ogr(x, quiet, check_ring_dir = check_ring_dir,\n\t\t\tstringsAsFactors = stringsAsFactors, geometry_column = geometry_column,\n\t\t\toptional = optional, ...)\n\t}\n}"

const rtdal006627Source0009 = `read_sf <- function(..., quiet = TRUE, stringsAsFactors = FALSE, as_tibble = TRUE) {
	st_read(..., quiet = quiet, stringsAsFactors = stringsAsFactors, as_tibble = as_tibble)
}`

const rtdal006627Source0010 = `clean_columns = function(obj, factorsAsCharacter) {
	permitted = c("character", "integer", "numeric", "Date", "POSIXct", "logical", "list")
	for (i in seq_along(obj)) {
		if (is.factor(obj[[i]])) {
			obj[[i]] = if (factorsAsCharacter)
					as.character(obj[[i]])
				else
					as.numeric(obj[[i]])
		}
		if (! inherits(obj[[i]], permitted)) {
			if (inherits(obj[[i]], "POSIXlt"))
				obj[[i]] = as.POSIXct(obj[[i]])
			else if (is.numeric(obj[[i]]))
				obj[[i]] = as.numeric(obj[[i]]) # strips class
		}
		if (is.character(obj[[i]]))
			obj[[i]] = enc2utf8(obj[[i]])
	}
	ccls.ok = vapply(obj, function(x) inherits(x, permitted), TRUE)
	if (any(!ccls.ok)) {
		# nocov start
                nms <- names(obj)[!ccls.ok]
                cls <- sapply(obj, function(x) paste(class(x), collapse=";"))[!ccls.ok]
                warning("Dropping column(s) ", paste(nms, collapse=","),
                    " of class(es) ", paste(cls, collapse=","))
		obj = obj[ccls.ok]
		# nocov end
	}
	colclasses = vapply(obj, function(x) permitted[ which(inherits(x, permitted, which = TRUE) > 0)[1] ] , "")
	# check that list columns contain raw vectors:
	for (lc in which(colclasses == "list")) {
		if (!all(sapply(obj[[lc]], inherits, "raw")))
			stop("list columns are only allowed with raw vector contents")
	}
	structure(obj, colclasses = colclasses)
}`

const rtdal006627Source0011 = `abbreviate_shapefile_names = function(x) {
# from: rgdal/pkg/R/ogr_write.R:
    fld_names <- names(x)
#   if (!is.null(encoding)) {
#       fld_names <- iconv(fld_names, from=encoding, to="UTF-8")
#   }
	if (any(nchar(fld_names) > 10)) {
		fld_names <- abbreviate(fld_names, minlength = 7)
		warning("Field names abbreviated for ESRI Shapefile driver")
		if (any(nchar(fld_names) > 10))
			fld_names <- abbreviate(fld_names, minlength = 5) # nocov
	}
# fix for dots in DBF field names 121124
	if (length(wh. <- grep("\\.", fld_names) > 0))
		fld_names[wh.] <- gsub("\\.", "_", fld_names[wh.])

	if (anyDuplicated(fld_names))
		stop("Non-unique field names") # nocov

	names(x) = fld_names
	x
}`

const rtdal006627Source0012 = `st_write = function(obj, dsn, layer, ...) UseMethod("st_write")`

const rtdal006627Source0013 = `st_write.sfc = function(obj, dsn, layer, ...) {
	if (missing(layer))
		st_write.sf(st_sf(geom = obj), dsn, ...)
	else
		st_write.sf(st_sf(geom = obj), dsn, layer, ...)
	invisible(obj)
}`

const rtdal006627Source0014 = "st_write.sf = function(obj, dsn, layer = NULL, ...,\n\t\tdriver = guess_driver_can_write(dsn),\n\t\tdataset_options = NULL, layer_options = NULL, quiet = FALSE, factorsAsCharacter = TRUE,\n\t\tappend = NA, delete_dsn = FALSE, delete_layer = !is.na(append) && !append,\n\t\tfid_column_name = NULL, config_options = character(0)) {\n\n\treturn_obj = ret = obj\n\tif (!is.null(list(...)$update)) {\n\t\t.Deprecated(\"append\", old = \"update\") # deprecated at 0.9-0\n\t\tif (is.na(append))\n\t\t\tappend = list(...)$update\n\t}\n#\telse if (length(list(...)))\n#\t\tstop(paste(\"unrecognized argument(s)\", names(list(...)), \"\\n\"))\n\tif (missing(dsn))\n\t\tstop(\"dsn should specify a data source or filename\")\n\tif (inherits(dsn, c(\"DBIObject\", \"PostgreSQLConnection\", \"Pool\"))) {\n\t\tif (inherits(dsn, \"Pool\")) {\n\t\t\tif (! requireNamespace(\"pool\", quietly = TRUE)) # nocov start\n\t\t\t\tstop(\"package pool required, please install it first\")\n\t\t\tdsn = pool::poolCheckout(dsn)\n\t\t\ton.exit(pool::poolReturn(dsn)) # nocov end\n\t\t}\n\n\t\tif (is.null(layer)) {\n\t\t\tlayer = deparse(substitute(obj))\n\t\t}\n\n\t\tif (is.na(append)) {\n\t\t\tappend = FALSE\n\t\t}\n\n\t\t# check arguments\n\t\tcl <- as.list(match.call())[-1L]\n\t\tif (\"overwrite\" %in% names(cl)) {\n\t\t\tstop(\"Argument `overwrite` in `st_write()` is deprecated, use `delete_layer` instead.\", call. = FALSE)\n\t\t}\n\n\t\tcheck_append_delete(append, delete_layer)\n\t\tdbWriteTable(dsn, name = layer, value = obj,\n\t\t\t\t\t append = append, overwrite = delete_layer,\n\t\t\t\t\t factorsAsCharacter = factorsAsCharacter, ...)\n\t\treturn(invisible(return_obj))\n\t} else if (!inherits(dsn, \"character\")) { # add methods for other dsn classes here...\n\t\tstop(paste(\"no st_write method available for dsn of class\", class(dsn)[1]))\n\t}\n\n\tif (!is.na(append) && append == FALSE && delete_layer == FALSE)\n\t\tstop(\"cannot replace a layer if delete_layer is FALSE\")\n\n\tif (is.null(layer))\n\t\tlayer <- file_path_sans_ext(basename(dsn))\n\n\tif (length(dsn) == 1 && length(grep(\"~\", dsn)) == 1) # resolve ~\n\t\tdsn = normalizePath(dsn, mustWork = FALSE) # nocov\n\n\t# this seems to be always a good idea:\n\tdsn = enc2utf8(dsn)\n\n\t# handle the case where obj does not have a geometry column:\n\tif (write_geometries <- inherits(obj, \"sf\")) {\n\t\tgeom = st_geometry(obj)\n\t\tobj[[attr(obj, \"sf_column\")]] = NULL\n\t\tif (is.na(st_crs(geom))) {\n\t\t\tmessage('writing: substituting ENGCRS[\"Undefined Cartesian SRS with unknown unit\"] for missing CRS')\n\t\t\tst_crs(geom) = st_crs(\"ENGCRS[\\\"Undefined Cartesian SRS with unknown unit\\\",EDATUM[\\\"Unknown engineering datum\\\"],CS[Cartesian,2],AXIS[\\\"X\\\",unspecified,ORDER[1],LENGTHUNIT[\\\"unknown\\\",0]],AXIS[\\\"Y\\\",unspecified,ORDER[2],LENGTHUNIT[\\\"unknown\\\",0]]]\")\n\t\t}\n\t} else { # create fake geometries:\n\t\tv = vector(\"list\", nrow(obj))\n\t\tv[seq_len(nrow(obj))] = list(st_point())\n\t\tgeom = st_sfc(v)\n\t}\n\n\tif (driver == \"ESRI Shapefile\") { # remove trailing .shp from layer name\n\t\tlayer = sub(\".shp$\", \"\", layer)\n\t\tobj = abbreviate_shapefile_names(obj)\n\t}\n\n\tobj = clean_columns(as.data.frame(obj), factorsAsCharacter)\n\t# this attaches attr colclasses\n\n\tnames(obj) = enc2utf8(names(obj))\n\n\tdim = if (length(geom) == 0)\n\t\t\t\"XY\"\n\t\telse\n\t\t\tclass(geom[[1]])[1]\n\n\tfids = if (!is.null(fid_column_name)) {\n\t\t\tfids = as.character(obj[[fid_column_name]])\n\t\t\tobj[[fid_column_name]] = NULL\n\t\t\tfids\n\t\t} else\n\t\t\tcharacter(0)\n\n\tret = CPL_write_ogr(obj, dsn, layer, driver,\n\t\tas.character(dataset_options), as.character(layer_options),\n\t\tgeom, dim, fids, config_options, quiet, append, delete_dsn, delete_layer,\n\t\twrite_geometries, getOption(\"width\"))\n\tif (ret == 1) { # try through temp file:\n\t\ttmp = tempfile(fileext = paste0(\".\", tools::file_ext(dsn))) # nocov start\n\t\tif (!quiet)\n\t\t\tmessage(paste(\"writing first to temporary file\", tmp))\n\t\tif (CPL_write_ogr(obj, tmp, layer, driver,\n\t\t\t\tas.character(dataset_options), as.character(layer_options),\n\t\t\t\tgeom, dim, fids, config_options, quiet, append, delete_dsn, delete_layer,\n\t\t\t\twrite_geometries, getOption(\"width\")) == 1)\n\t\t\tstop(paste(\"failed writing to temporary file\", tmp))\n\t\tif (!file.copy(tmp, dsn, overwrite = append || delete_dsn || delete_layer))\n\t\t\tstop(paste(\"copying\", tmp, \"to\", dsn, \"failed\"))\n\t\tif (!file.remove(tmp))\n\t\t\twarning(paste(\"removing\", tmp, \"failed\"))\n\t} # nocov end\n\tinvisible(return_obj)\n}"

const rtdal006627Source0015 = `st_write.data.frame <- function(obj, dsn, layer = NULL, ...) {
	sf = try(st_as_sf(obj), silent = TRUE)
	if (!inherits(sf, "try-error"))
		st_write.sf(sf, dsn = dsn, layer = layer, ...)
	else
		st_write.sf(obj, dsn = dsn, layer = layer, ...)
	invisible(obj)
}`

const rtdal006627Source0016 = `write_sf <- function(..., quiet = TRUE, append = FALSE, delete_layer = !append) {
	st_write(..., quiet = quiet, append = append, delete_layer = delete_layer)
}`

const rtdal006627Source0017 = `st_drivers = function(what = "vector", regex) {
	ret = CPL_get_gdal_drivers(0)
	row.names(ret) = ret$name
	ret = switch(what,
		vector = ret[ret$is_vector,],
		raster = ret[ret$is_raster,],
		ret)
	if (missing(regex))
		ret
	else {
		fn = function(x, pattern) any(grepl(x, pattern = pattern))
		ret[apply(ret[c("name", "long_name")], 1, fn, pattern = regex), ]
	}
}`

const rtdal006627Source0018 = `print.sf_layers = function(x, ...) {
	n_gt = max(sapply(x$geomtype, length))
	x$geomtype = vapply(x$geomtype, function(x) paste(x, collapse = ", "), "")
	cat(paste("Driver:", x$driver, "\n"))
	x$driver = NULL
	x$features[x$features < 0] = NA
	cat("Available layers:\n")
	if (length(x$name) == 0) {
		cat("<none>\n") # nocov
		invisible(x)    # nocov
	} else {
		crs = sapply(x$crs, function(crs) crs$input)
		x$crs = crs
		df = data.frame(unclass(x))
		gt = if (n_gt > 1)
				"geometry_types"
			else
				"geometry_type"
		names(df) = c("layer_name", gt, "features", "fields", "crs_name")
		print(df)
		invisible(df)
	}
}`

const rtdal006627Source0019 = `st_layers = function(dsn, options = character(0), do_count = FALSE) {
	if (missing(dsn))
		stop("dsn should specify a data source or filename")
	if (length(dsn) == 1 && file.exists(dsn))
		dsn = enc2utf8(normalizePath(dsn))
	ret = CPL_get_layers(dsn, options, do_count)
	if (length(ret[[1]]) > 0) {
		Encoding(ret[[1]]) <- "UTF-8"
		ret[[1]] <- enc2native(ret[[1]])
	}
	structure(ret, row.names = seq_along(ret[[1]]), class = c("sf_layers", "data.frame"))
}`

const rtdal006627Source0020 = `guess_driver = function(dsn) {
  stopifnot(is.character(dsn))
  stopifnot(length(dsn) == 1)

	# find match: try extension first
	drv = extension_map[tolower(tools::file_ext(dsn))]
	if (is_db_driver(dsn))
		drv = prefix_map[tolower(strsplit(dsn, ":")[[1]][1])]

	drv <- unlist(drv)

	if (is.null(drv)) {
	  # no match
	  return(NA)
	}
	drv
}`

const rtdal006627Source0028 = "check_append_delete <- function(append, delete) {\n\tif (append && delete) {\n\t\tstop(\"`delete_layer` and `append` cannot both be `TRUE`\", call. = FALSE)\n\t}\n}"

