const rtdal006632Source0015 = "st_zm.sfg <- function(x, ..., drop = TRUE, what = \"ZM\") {\n\tif (drop && what == \"ZM\") {\n\t\tret = if (is.list(x))\n\t\t\tlapply(x, st_zm, drop = drop, what = what)\n\t\telse if (is.matrix(x))\n\t\t\tx[, 1:2, drop = FALSE]\n\t\telse\n\t\t\tx[1:2]\n\t\tstructure(ret, class = c(\"XY\", class(x)[2:3]))\n\t} else if (!drop && what == \"Z\") {\n\t\tif (class(x)[1] != \"XY\")\n\t\t\tstop(\"adding Z only supported for XY geometries\")\n\t\tret = if (is.list(x))\n\t\t\tlapply(x, st_zm, drop = drop, what = what)\n\t\telse if (is.matrix(x))\n\t\t\tcbind(unclass(x), 0)\n\t\telse\n\t\t\tc(unclass(x), 0)\n\t\tstructure(ret, class = c(\"XYZ\", class(x)[2:3]))\n\t} else\n\t\tstop(\"this combination of `x', `drop' and `what' is not implemented\")\n}"

