const rtdal006634Source0001 = `sgbp = function(x, predicate, region.id, ncol, sparse = TRUE, remove_self = FALSE, 
				retain_unique = FALSE) {
	if (remove_self || retain_unique) {
		if (length(x) != ncol)
			stop("remove_self or retain_unique only work for square sparse matrices")
		x = if (retain_unique) # (includes doing remove_self)
				mapply(function(x, y) { x[x > y] }, x, seq_along(x), SIMPLIFY = FALSE)
			else # remove_self 
				mapply(setdiff, x, seq_along(x), SIMPLIFY = FALSE)
	}
	ret = structure(x,
		predicate = predicate,
		region.id = region.id,
		remove_self = remove_self,
		retain_unique = retain_unique,
		ncol = ncol,
		class = c("sgbp", "list"))
	if (! sparse)
		as.matrix(ret)
	else
		ret
}`

const rtdal006634Source0002 = "print.sgbp = function(x, ..., n = 10, max_nb = 10) {\n\tn = min(length(x), n)\n\thd = paste0(\"Sparse geometry binary predicate list of length \", length(x), \", \",\n\t \t\"where the predicate was `\", attr(x, \"predicate\"), \"'\")\n\tif (isTRUE(attr(x, \"retain_unique\")))\n\t\thd = paste0(hd, \", with retain_unique = TRUE\")\n\telse if (isTRUE(attr(x, \"remove_self\")))\n\t\thd = paste0(hd, \", with remove_self = TRUE\")\n\tcat(strwrap(hd), sep = \"\\n\")\n\tif (n < length(x))\n\t\tcat(\"first \", n, \" elements:\\n\", sep = \"\")\n\tnbh = function(i, m) {\n\t\tX = x[[i]]\n\t\tend = if (length(X) > m) \", ...\" else \"\"\n\t\tcat(\" \", i, \": \", sep = \"\")\n\t\tif (length(X))\n\t\t\tcat(paste(head(X, m), collapse = \", \"), end, \"\\n\", sep = \"\")\n\t\telse\n\t\t\tcat(\"(empty)\\n\")\n\t}\n\tlapply(1:n, nbh, m = max_nb)\n\tinvisible(x)\n}"

const rtdal006634Source0004 = `as.matrix.sgbp = function(x, ...) {
	nc = attr(x, "ncol")
	get_vec = function(x, n) { v = rep(FALSE, n); v[x] = TRUE; v }
	do.call(rbind, lapply(x, get_vec, n = nc))
}`

const rtdal006634Source0006 = `Ops.sgbp = function(e1, e2) {
	switch(.Generic, 
	   "!" = {
			nc = 1:attr(e1, "ncol")
			sgbp(lapply(e1, function(x) setdiff(nc, x)),
				predicate = paste0("!", attr(e1, "predicate")),
				region.id = attr(e1, "region.id"),
				ncol = attr(e1, "ncol"))
	   },
	   "==" = (length(e1) == length(e2)) && all(mapply(function(x,y) identical(x, y), e1, e2)), 
	   "!=" = return(!(e1 == e2)),
		stop("only operators !, == and != are supported for sgbp objects")
	)
}`

const rtdal006634Source0007 = `as.data.frame.sgbp = function(x, ...) {
	data.frame(row.id = rep(seq_along(x), lengths(x)), col.id = unlist(x))
}`

const rtdal006634Source0009 = `setAs("sgbp", "sparseMatrix", function(from) {
	if (! requireNamespace("Matrix", quietly = TRUE))
		stop("package Matrix required, please install it first")
	idx = as.data.frame(from)
	Matrix::sparseMatrix(i = idx$row.id, j = idx$col.id, x = 1)
})`

