const rtdal006638Source0001 = `gdal_read = function(x, ..., options = character(0), driver = character(0), read_data = TRUE, NA_value = NA_real_,
		RasterIO_parameters = list()) {
	if (is.numeric(read_data)) {
		max_cells = as.double(read_data)
		read_data = FALSE
	} else
		max_cells = as.double(-1.)
	CPL_read_gdal(as.character(x), as.character(options), as.character(driver), 
		as.logical(read_data), as.double(NA_value), RasterIO_parameters, max_cells)
}`

const rtdal006638Source0002 = `gdal_write = function(x, ..., file, driver = "GTiff", options = character(0), type = "Float32", 
		NA_value = NA_real_, geotransform, update = FALSE, scale_offset = c(1.0, 0.0)) {

	if (!requireNamespace("stars", quietly = TRUE))
		stop("stars required: install that first") # nocov

	if (any(scale_offset != c(1.0, 0.0)) && packageVersion("sf") <= "1.0-9")
		warning("handling scale_offset requires sf > 1.0-9")
	d = stars::st_dimensions(x)
	xydims = attr(d, "raster")$dimensions
	if (!isTRUE(all.equal(match(xydims, names(d)), 1:2)))
		stop("x and y raster dimensions need to be in place 1 and 2")
	from = c(d[[1]]$from, d[[2]]$from) - 1
	dims = c(d[[1]]$to, d[[2]]$to)
	if (length(d) == 3)
		dims = c(dims, d[[3]]$to - d[[3]]$from + 1)

	if (inherits(x, "stars_proxy")) {
		mat = matrix(0, 0, 0) # nocov start
		only_create = TRUE # don't write any pixel data
		if (!all(from == 0))
			warning("writing raster to original size") # otherwise, geotransform needs to be modified
		from = c(0, 0) # nocov end
	} else {
		mat = x[[1]]
		dm = dim(mat)
		if (is.factor(mat)) {
			rgba = NULL
			ex = attr(mat, "exclude")
			if (is.null(ex))
				lev = c("", levels(mat)) # add "" for value 0: R factors start at 1
			else {
				if (any(ex)) {
					lev = vector("character", length(ex)) # fills with ""
					lev[!ex] = levels(mat)
					rgba = if (!is.null(co <- attr(mat, "rgba"))) {
						n = length(ex)
						coltab = cbind(rep(0., n), rep(0, n), rep(0, n), rep(255, n))
						coltab[!ex,] = co
						coltab 
					}
					values = which(!ex) - 1
					mat = values[as.numeric(mat)]
				} else
					lev = levels(mat)
			}
			mat = structure(mat, class = NULL, levels = lev, dim = dm, rgba = rgba)
		}
		only_create = FALSE # write x too
		if (! update) {
			if (!all(from == 0))
				stop("cannot write sub-rasters only")
			if (!all(dims == dm))
				stop("dimensions don't match")
		}
		dim(mat) = c(dm[1], prod(dm[-1])) # flatten to 2-D matrix
	}
	if (length(dims) == 2)
		dims = c(dims, 1) # one band
	else if (is.character(d[[3]]$values)) # add band descriptions?
		attr(mat, "descriptions") = d[[3]]$values

	CPL_write_gdal(mat, file, driver, options, type, dims, from, geotransform,
		st_crs(x)[[2]], as.double(NA_value), scale_offset, create = !update, 
		only_create = only_create)
}`

const rtdal006638Source0005 = "st_as_sfc.dimensions = function(x, ..., as_points = NA, use_cpp = TRUE, which = seq_len(prod(dim(x))),\n\t\tgeotransform) {\n\n\tif (is.na(as_points))\n\t\tstop(\"as_points should be set to TRUE (`points') or FALSE (`polygons')\")\n\n\txy2sfc = function(cc, dm, as_points) { # form points or polygons from a matrix with corner points\n\t\tif (as_points)\n\t\t\tunlist(apply(cc, 1, function(x) list(st_point(x))), recursive = FALSE)[which]\n\t\telse {\n\t\t\tstopifnot(prod(dm) == nrow(cc))\n\t\t\tlst = vector(\"list\", length = prod(dm - 1))\n\t\t\tfor (y in 1:(dm[2]-1)) {\n\t\t\t\tfor (x in 1:(dm[1]-1)) {\n\t\t\t\t\ti1 = (y - 1) * dm[1] + x      # top-left\n\t\t\t\t\ti2 = (y - 1) * dm[1] + x + 1  # top-right\n\t\t\t\t\ti3 = (y - 0) * dm[1] + x + 1  # bottom-right\n\t\t\t\t\ti4 = (y - 0) * dm[1] + x      # bottlom-left\n\t\t\t\t\tlst[[ (y-1)*(dm[1]-1) + x ]] = st_polygon(list(cc[c(i1,i2,i3,i4,i1),]))\n\t\t\t\t}\n\t\t\t}\n\t\t\tlst[which]\n\t\t}\n\t}\n\n\traster = attr(x, \"raster\")\n\txy_names = raster$dimensions\n\txd = x[[ xy_names[1] ]]\n\tyd = x[[ xy_names[2] ]]\n\tcc = if (!is.na(xd$offset) && !is.na(yd$offset)) {\n\t\txy = if (as_points) # grid cell centres:\n\t\t\t\texpand.grid(x = seq(xd$from, xd$to) - 0.5, y = seq(yd$from, yd$to) - 0.5)\n\t\t\telse # grid corners: from 0 to n\n\t\t\t\texpand.grid(x = seq(xd$from - 1, xd$to), y = seq(yd$from - 1, yd$to))\n\t\txy_from_colrow(as.matrix(xy), geotransform)\n\t} else if (is.null(xd$values) || is.null(yd$values)) { # only one of [xd|yd] has $values:\n\t\tif (!requireNamespace(\"stars\", quietly = TRUE)) # nocov start\n\t\t\tstop(\"stars required: install that first\")\n\t\tif (! as_points)\n\t\t\tstop(\"st_as_sfc(): mixed regular and rectilinear dimensions only supported if as_points = TRUE\")\n\t\tas.matrix(st_coordinates(x)) # nocov end\n\t} else { # both xd and yd have $values:\n\t\texpand = function(x) { # might fail on the poles or dateline\n\t\t\td = diff(x)\n\t\t\tc(x[1] - 0.5 * d[1], x + 0.5 * c(d, tail(d, 1)))\n\t\t}\n\t\tif (raster$curvilinear) { # expand jointly:\n\t\t\tif (!as_points && all(dim(xd$values) == dim(x)[xy_names])) { # expand from points to cells/polygons: \n\t\t\t\txd$values = apply((apply(xd$values, 1, expand)), 1, expand)\n\t\t\t\tyd$values = apply((apply(yd$values, 1, expand)), 1, expand)\n\t\t\t}\n\t\t\tcbind(as.vector(xd$values), as.vector(yd$values))\n\t\t} else { # rectlinear: expand independently\n\t\t\tif (! as_points) {\n\t\t\t\txd$values = if (inherits(xd$values, \"intervals\"))\n\t\t\t\t\t\tc(xd$values$start, tail(xd$values$end, 1))\n\t\t\t\t\telse\n\t\t\t\t\t\texpand(xd$values)\n\t\t\t\tyd$values = if (inherits(yd$values, \"intervals\"))\n\t\t\t\t\t\tc(yd$values$start, tail(yd$values$end, 1))\n\t\t\t\t\telse\n\t\t\t\t\t\texpand(yd$values)\n\t\t\t} else {\n\t\t\t\tif (inherits(xd$values, \"intervals\"))\n\t\t\t\t\txd$values = 0.5 * (xd$values$start + xd$values$end)\n\t\t\t\tif (inherits(yd$values, \"intervals\"))\n\t\t\t\t\tyd$values = 0.5 * (yd$values$start + yd$values$end)\n\t\t\t}\n\t\t\tas.matrix(expand.grid(x = xd$values, y = yd$values))\n\t\t}\n\t}\n\tdims = dim(x) + !as_points\n\tif (use_cpp) {\n\t\tbb = if (cc_has_NAs <- anyNA(cc))\n\t\t\t\tbbox.Mtrx(na.omit(cc))\n\t\t\telse\n\t\t\t\tbbox.Mtrx(cc)\n\t\tstructure(CPL_xy2sfc(cc, as.integer(dims), as_points, as.integer(which), cc_has_NAs), \n\t\t\tcrs = st_crs(xd$refsys), n_empty = 0L, bbox = bb)\n\t} else\n\t\tst_sfc(xy2sfc(cc, dims, as_points), crs = xd$refsys)\n}"

const rtdal006638Source0009 = `gdal_subdatasets = function(file, options = character(0), name = TRUE) {
	if (!("SUBDATASETS" %in% CPL_get_metadata(file, NA_character_, options)))
		list()
	else {
		md = gdal_metadata(file, "SUBDATASETS", options, TRUE)
		if (name)
			md[seq(1, length(md), by = 2)]
		else
			md[seq(2, length(md), by = 2)]
	}
}`

const rtdal006638Source0010 = `gdal_polygonize = function(x, mask = NULL, file = tempfile(), driver = "GTiff", use_integer = TRUE,
		geotransform, breaks = classInt::classIntervals(na.omit(as.vector(x[[1]])))$brks, 
		use_contours = FALSE, contour_lines = FALSE, connect8 = FALSE, ...) {
	gdal_write(x, file = file, driver = driver, geotransform = geotransform) # nocov start
	on.exit(unlink(file))
	mask_name = if (!is.null(mask)) {
			mask_name = tempfile()
			gdal_write(mask, file = mask_name, driver = driver, geotransform = geotransform)
			on.exit(unlink(mask_name))
			mask_name
		} else
			character(0)
	contour_options = if (use_contours) { # construct contour_options:
			nbreaks = breaks
			if (max(breaks) == max(x[[1]], na.rm = TRUE)) # expand, because GDAL will not include interval RHS
				nbreaks[length(nbreaks)] = breaks[length(breaks)] * 1.01
			c(paste0("FIXED_LEVELS=", paste0(nbreaks, collapse = ",")),
			"ELEV_FIELD=0", "ELEV_FIELD_MIN=1", "ELEV_FIELD_MAX=2",
			paste0("POLYGONIZE=", ifelse(contour_lines, "NO", "YES")))
		} else
			character(0)

	options = if (connect8)
			"8CONNECTED=8"
		else
			character(0)

	mem = ifelse(compareVersion(sf_extSoftVersion()["GDAL"], "3.11.0") >= 0, "MEM", "Memory")
	pol = CPL_polygonize(file, mask_name, "GTiff", mem, "foo", options, 0, 
		contour_options, use_contours, use_integer)
	out = process_cpl_read_ogr(pol, quiet = TRUE)
	names(out)[1] = names(x)[1]
	if (! contour_lines && use_contours) {
#		if (out$Min[1] == 0 && out$Min[1] > min(breaks))
#			out$Min[1] = -Inf
#
# https://github.com/r-spatial/sf/pull/1608 : 

		i <- match(out$Max[1], sort(breaks))
		out$Min[1] = if (!is.na(i) && i > 1)
				sort(breaks)[i - 1]
			else 
				-Inf

		out$Max[out$Max == 2^32 - 1] = Inf
		f = paste0("[", out$Min, ",", out$Max, ")")
		out[[1]] = factor(f, levels = f)
	} else
		out$Min = out$Max = NULL
	out # nocov end
}`

const rtdal006638Source0014 = `gdal_write_mdim = function(file, driver, dimx, cdl, wkt, xy, ...,
						   root_group_options = character(0), options = character(0),
						   as_float = TRUE) {
    CPL_write_mdim(file, driver, dimx, cdl, wkt, xy, root_group_options, options, as_float)
}`

