const rtdal006641Source0010 = `select.sf <- function(.data, ...) {

	if (!requireNamespace("tidyselect", quietly = TRUE))
		stop("tidyselect required: install that first") # nocov
	loc = tidyselect::eval_select(quote(c(...)), .data)

	sf_column = attr(.data, "sf_column")
	sf_column_loc = match(sf_column, names(.data))

	if (length(sf_column_loc) != 1 || is.na(sf_column_loc))
		stop("internal error: can't find sf column") # nocov

	agr = st_agr(.data)
	#vars = names(.data)[setdiff(loc, sf_column_loc)] # see #1886, change into:
	lloc = loc
	if (sf_column_loc %in% loc)
		lloc = lloc[loc != sf_column_loc]
	vars = names(.data)[lloc]

	sf_column_loc_loc = match(sf_column_loc, loc)
	if (is.na(sf_column_loc_loc)) {
		# The sf column was subsetted out, select it back in
		new_agr = setNames(agr[vars], names(loc))
		loc = c(loc, sf_column_loc)
		names(loc)[[length(loc)]] = sf_column
	} else {
		# The sf column was not subsetted out but it might have been renamed
		sf_column = names(loc[sf_column_loc_loc])
		new_agr = setNames(agr[vars], setdiff(names(loc), sf_column))
	}

	ret = .data
	class(ret) = setdiff(class(ret), "sf")
	ret = ret[loc]
	names(ret) = names(loc)

	st_set_agr(st_as_sf(ret, sf_column_name = sf_column), new_agr)
}`

const rtdal006641Source0011 = "rename.sf <- function(.data, ...) {\n\n\tif (!requireNamespace(\"tidyselect\", quietly = TRUE))\n\t\tstop(\"tidyselect required: install that first\") # nocov\n\tloc = tidyselect::eval_rename(quote(c(...)), .data)\n\n\tsf_column = attr(.data, \"sf_column\")\n\tsf_column_loc = match(sf_column, names(.data))\n\n\tif (length(sf_column_loc) != 1 || is.na(sf_column_loc))\n\t\tstop(\"internal error: can't find sf column\") # nocov\n\n\tagr = st_agr(.data)\n\tagr_loc = match(names(agr), setdiff(names(.data), sf_column))\n\n\tif (anyNA(agr_loc))\n\t\tstop(\"internal error: can't find `agr` columns\") # nocov\n\n\tvars_loc = loc[loc %in% agr_loc]\n\n\t# https://github.com/r-spatial/sf/issues/1472\n\t# but only fixes for the single sfc column case\n\tsfcs = which(sapply(.data, inherits, \"sfc\"))\n\tif (length(vars_loc) == 1 && any(vars_loc > sfcs[1])) {\n\t\tw = which(vars_loc > sfcs)\n\t\tvars_loc[w] = vars_loc[w] - 1\n\t}\n\n\tnames(agr)[vars_loc] = names(vars_loc)\n\n\tsf_column_loc_loc = match(sf_column_loc, loc)\n\tif (!is.na(sf_column_loc_loc))\n\t\tsf_column = names(loc[sf_column_loc_loc])\n\n\tret = .data\n\tclass(ret) = setdiff(class(ret), \"sf\")\n\tnames(ret)[loc] = names(loc)\n\n\tst_set_agr(st_as_sf(ret, sf_column_name = sf_column), agr)\n}"

const rtdal006641Source0012 = `rename_with.sf = function(.data, .fn, .cols, ...) {
	if (!requireNamespace("rlang", quietly = TRUE))
		stop("rlang required: install that first") # nocov
	.fn = rlang::as_function(.fn)
	is_tibble = inherits(.data, "tbl")
	
	sf_column = attr(.data, "sf_column")
	sf_column_loc = match(sf_column, names(.data))
	
	if (length(sf_column_loc) != 1 || is.na(sf_column_loc))
		stop("internal error: can't find sf column") # nocov
	
	agr = st_agr(.data)
	
	.data = as.data.frame(.data)
	ret = if (missing(.cols)) {
		if (!requireNamespace("tidyselect", quietly = TRUE)) {
			stop("tidyselect required: install that first") # nocov
		}
		dplyr::rename_with(
			.data = .data,
			.fn = .fn,
			.cols = tidyselect::everything(), 
			...
		)
	} else {
		dplyr::rename_with(
			.data = .data,
			.fn = .fn,
			.cols = {{ .cols }}, 
			...
		)
	}
	if (is_tibble)
		ret = dplyr::as_tibble(ret)
	ret = st_as_sf(ret, sf_column_name = names(ret)[sf_column_loc])
	
	names(agr) = .fn(names(agr), ...)
	st_agr(ret) = agr
	ret
}`

