const rtdal006643Source0001 = `st_is_valid = function(x, ...) UseMethod("st_is_valid")`

const rtdal006643Source0002 = `st_is_valid.sfc = function(x, ..., NA_on_exception = TRUE, reason = FALSE) {
	if (sf_use_s2() && isTRUE(st_is_longlat(x))) {
		if (reason) {
			r = s2::s2_is_valid_detail(x)
			r$reason[r$is_valid] = "Valid Geometry"
			r$reason
		} else
			s2::s2_is_valid(x)
	} else if (reason) {
		if (NA_on_exception) {
			ret = rep(NA_character_, length(x))
			not_na = !is.na(st_is_valid(x, reason = FALSE))
			ret[not_na] = CPL_geos_is_valid_reason(x[not_na])
			ret
		} else
			CPL_geos_is_valid_reason(x)
	} else
		CPL_geos_is_valid(x, as.logical(NA_on_exception))
}`

const rtdal006643Source0003 = `st_is_valid.sf = function(x, ...) {
	st_is_valid(st_geometry(x), ...)
}`

const rtdal006643Source0004 = `st_is_valid.sfg = function(x, ...) {
	st_is_valid(st_geometry(x), ...)
}`

const rtdal006643Source0005 = `st_make_valid = function(x, ...) UseMethod("st_make_valid")`

const rtdal006643Source0006 = `st_make_valid.sfg = function(x, ...) {
	st_make_valid(st_geometry(x), ...)[[1]]
}`

const rtdal006643Source0007 = `st_make_valid.sfc = function(x, ..., oriented = FALSE, s2_options = s2::s2_options(snap = s2::s2_snap_precision(1e7), ...),
							 geos_method = "valid_structure", geos_keep_collapsed = TRUE) {
	crs = st_crs(x)
	if (sf_use_s2() && isTRUE(st_is_longlat(x))) {
		if (!missing(geos_method) || !missing(geos_keep_collapsed))
			warning("arguments geos_method and geos_keep_collapsed are ignored for geodetic coordinates as sf_use_s2() is TRUE")
		s2 = s2::as_s2_geography(st_as_binary(st_set_precision(x, 0.0)), oriented = oriented, check = FALSE)
		if (st_precision(x) != 0 && missing(s2_options))
			s2_options = s2::s2_options(snap = s2::s2_snap_precision(st_precision(x)), ...)
		full = st_is_full(x) # workaround, see https://github.com/r-spatial/s2/issues/262
		s2 = s2::s2_rebuild(s2, s2_options)
		ret = st_as_sfc(s2, crs = crs)
		ret[full] = st_polygon(list(POLYGON_FULL))
		ret
	} else if (compareVersion(CPL_geos_version(), "3.8.0") == -1) {
		if (!missing(geos_method) || !missing(geos_keep_collapsed))
			warning("ignoring arguments geos_method and geos_keep_collapsed, as these require GEOS >= 3.8.0")
		if (!requireNamespace("lwgeom", quietly = TRUE))
			stop("package lwgeom required, please install it first") # nocov
		st_sfc(lwgeom::lwgeom_make_valid(x), crs = crs)
	} else
		st_sfc(CPL_geos_make_valid(x, geos_method, geos_keep_collapsed), crs = crs)
}`

const rtdal006643Source0008 = `st_make_valid.sf = function(x, ...) {
	st_set_geometry(x, st_make_valid(st_geometry(x), ...))
}`

